import { Hono } from 'hono';
import { getCookie, setCookie, deleteCookie } from 'hono/cookie';

type Env={DB:D1Database;MEDIA?:R2Bucket;ASSETS:Fetcher;SESSION_SECRET:string;TOKEN_ENCRYPTION_KEY?:string;RESEND_API_KEY?:string;RESEND_FROM_EMAIL?:string;ADMIN_OWNER_EMAIL?:string;SITE_NAME:string;PHONE:string;MAPS_URL:string;ADMIN_HOST?:string;INSTAGRAM_ACCESS_TOKEN?:string;INSTAGRAM_USER_ID?:string;INSTAGRAM_GRAPH_VERSION?:string;INSTAGRAM_APP_ID?:string;INSTAGRAM_APP_SECRET?:string;INSTAGRAM_REDIRECT_URI?:string;YOUTUBE_API_KEY?:string;YOUTUBE_CHANNEL_HANDLE?:string;GOOGLE_PLACES_API_KEY?:string;GOOGLE_PLACE_ID?:string};
const app=new Hono<{Bindings:Env}>();
function hostMatchesConfiguredAdmin(c:any){const configured=String(c.env.ADMIN_HOST||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/\/$/,'');if(!configured)return false;const requestHost=new URL(c.req.url).host.toLowerCase();return requestHost===configured||requestHost.split(':')[0]===configured.split(':')[0]}
app.use('*',async(c,next)=>{const sensitive=c.req.path.startsWith('/admin')||c.req.path.startsWith('/api/admin')||['/api/login','/api/logout','/api/me','/api/setup','/api/setup/status'].includes(c.req.path);if(sensitive&&!hostMatchesConfiguredAdmin(c))return c.notFound();if(c.req.method!=='GET'&&c.req.method!=='HEAD'&&c.req.method!=='OPTIONS'&&(c.req.path.startsWith('/api/admin')||['/api/login','/api/logout','/api/setup/request-code','/api/setup/verify-code','/api/setup/create'].includes(c.req.path))&&!sameOriginRequest(c))return c.json({error:'Invalid request origin'},403);await next()});
app.use('*',async(c,next)=>{await next();c.header('X-Content-Type-Options','nosniff');c.header('Referrer-Policy','strict-origin-when-cross-origin');c.header('X-Frame-Options','DENY');c.header('Permissions-Policy','camera=(),microphone=(),geolocation=()');c.header('Content-Security-Policy',"default-src 'self'; img-src 'self' data: https:; media-src 'self' https:; style-src 'self' 'unsafe-inline'; script-src 'self' https://www.youtube.com https://www.instagram.com; frame-src https://www.youtube.com https://www.youtube-nocookie.com https://www.instagram.com; connect-src 'self' https://www.youtube.com https://www.instagram.com; object-src 'none'; base-uri 'self'; frame-ancestors 'none'");});
const enc=new TextEncoder();
async function hmac(env:Env,value:string){if(!env.SESSION_SECRET||env.SESSION_SECRET.length<32)throw new Error('SESSION_SECRET is not configured correctly');const k=await crypto.subtle.importKey('raw',enc.encode(env.SESSION_SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);return crypto.subtle.sign('HMAC',k,enc.encode(value)).then(x=>btoa(String.fromCharCode(...new Uint8Array(x))));}
function b64u(bytes:ArrayBuffer|Uint8Array){const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);return btoa(String.fromCharCode(...a)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function unb64u(s:string){const t=s.replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(t+'='.repeat((4-t.length%4)%4)),x=>x.charCodeAt(0))}
async function tokenKey(env:Env,legacy=false){const secret=legacy||!env.TOKEN_ENCRYPTION_KEY?env.SESSION_SECRET:env.TOKEN_ENCRYPTION_KEY!;const digest=await crypto.subtle.digest('SHA-256',enc.encode(secret));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptToken(env:Env,value:string){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},await tokenKey(env),enc.encode(value));return `${b64u(iv)}.${b64u(ct)}`}
async function decryptToken(env:Env,value:string){const [ivS,ctS]=value.split('.');if(!ivS||!ctS)throw new Error('Invalid encrypted token');try{const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64u(ivS)},await tokenKey(env),unb64u(ctS));return new TextDecoder().decode(pt)}catch(e){if(env.TOKEN_ENCRYPTION_KEY){const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64u(ivS)},await tokenKey(env,true),unb64u(ctS));return new TextDecoder().decode(pt)}throw e}}
async function instagramRedirect(c:any){return c.env.INSTAGRAM_REDIRECT_URI||new URL('/api/instagram/callback',c.req.url).toString()}
async function getInstagramConnection(c:any){const row:any=await c.env.DB.prepare('SELECT * FROM instagram_integrations WHERE provider=? LIMIT 1').bind('instagram').first();if(row?.access_token_enc){try{return {...row,access_token:await decryptToken(c.env,row.access_token_enc)}}catch{}}if(c.env.INSTAGRAM_ACCESS_TOKEN&&c.env.INSTAGRAM_USER_ID)return {provider:'instagram',user_id:c.env.INSTAGRAM_USER_ID,access_token:c.env.INSTAGRAM_ACCESS_TOKEN,username:null,expires_at:null};return null}
async function refreshInstagramToken(c:any,conn:any){if(!conn?.access_token)return conn;const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';if(conn.expires_at&&Number(conn.expires_at)-Date.now()>7*86400000)return conn;if(!c.env.INSTAGRAM_APP_SECRET)return conn;const u=new URL(`https://graph.instagram.com/${version}/refresh_access_token`);u.searchParams.set('grant_type','ig_refresh_token');u.searchParams.set('access_token',conn.access_token);const r=await fetch(u);const d:any=await r.json();if(!r.ok||!d.access_token)return conn;const expiresAt=Date.now()+Number(d.expires_in||5184000)*1000;await c.env.DB.prepare('UPDATE instagram_integrations SET access_token_enc=?,expires_at=?,updated_at=CURRENT_TIMESTAMP WHERE provider=?').bind(await encryptToken(c.env,d.access_token),expiresAt,'instagram').run();return {...conn,access_token:d.access_token,expires_at:expiresAt}}
async function refreshInstagramMediaUrl(c:any,mediaId:string):Promise<string|null>{try{const conn=await getInstagramConnection(c);if(!conn)return null;const fresh=await refreshInstagramToken(c,conn);const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';const u=new URL(`https://graph.instagram.com/${version}/${encodeURIComponent(mediaId)}`);u.searchParams.set('fields','media_url');u.searchParams.set('access_token',fresh.access_token);const r=await fetch(u);const d:any=await r.json().catch(()=>({}));if(!r.ok||!d.media_url)return null;return String(d.media_url)}catch{return null}}
const PASSWORD_ITERATIONS=100000;
const STORAGE_LIMIT_BYTES=5368709120;
const MAX_GALLERY_SLOTS=21;
const MIN_GALLERY_SLOTS=3;
const MAX_PINNED_SLOTS=5;
const DEFAULT_GALLERY_CONFIG='{"slots":[{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"},{"type":"category","category":"Other"}],"columns":3}';
const DEFAULT_ABOUT_TEXT="At Impression Photography, we believe in capturing real moments, authentic emotions and the little details that make every celebration yours.\n\nFrom sunrise proposals by the Arabian Sea to quiet family mornings at home, every frame we capture is guided by one belief — your story deserves to be told exactly as it happened, without pretence. We don't just take pictures; we preserve the way a moment truly felt.";
async function hashPassword(p:string){const salt=crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',enc.encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:PASSWORD_ITERATIONS,hash:'SHA-256'},key,256);return `pbkdf2$${PASSWORD_ITERATIONS}$${btoa(String.fromCharCode(...salt))}$${btoa(String.fromCharCode(...new Uint8Array(bits)))}`;}
async function verifyPassword(p:string,stored:string){try{const [,it,s,b]=stored.split('$');const salt=Uint8Array.from(atob(s),x=>x.charCodeAt(0));const key=await crypto.subtle.importKey('raw',enc.encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:Number(it),hash:'SHA-256'},key,256);return btoa(String.fromCharCode(...new Uint8Array(bits)))===b}catch{return false}}
async function session(c:any,env:Env){const id=getCookie(c,'ip_session');if(!id)return null;const sig=getCookie(c,'ip_sig');if(!sig||await hmac(env,id)!==sig)return null;return c.env.DB.prepare('SELECT a.id,a.name,a.email,a.role FROM sessions s JOIN admins a ON a.id=s.admin_id WHERE s.id=? AND s.expires_at>? AND a.active=1').bind(id,Date.now()).first()}
function uid(){return crypto.randomUUID()}
function clientIp(c:any){return (c.req.header('CF-Connecting-IP')||c.req.header('X-Forwarded-For')||'unknown').split(',')[0].trim().slice(0,80)}
function sameOriginRequest(c:any){const origin=c.req.header('Origin');if(origin){try{return new URL(origin).origin===new URL(c.req.url).origin}catch{return false}}const referer=c.req.header('Referer');if(referer){try{return new URL(referer).origin===new URL(c.req.url).origin}catch{return false}}return true}
function textField(v:any,max:number){return String(v??'').trim().slice(0,max)}
function validEmail(v:any){const e=String(v??'').trim().toLowerCase();return e.length<=320&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}
function boundedInt(v:any,min:number,max:number,def=0){const n=Number(v);return Number.isInteger(n)&&n>=min&&n<=max?n:def}
function finiteNumber(v:any,min:number,max:number,def=0){const n=Number(v);return Number.isFinite(n)&&n>=min&&n<=max?n:def}
function validMediaUrl(v:string){if(!v)return true;if(v.startsWith('/media/'))return true;try{const u=new URL(v);return u.protocol==='https:'||u.protocol==='http:'}catch{return false}}
async function clearRateLimit(c:any,...keys:string[]){if(keys.length)await c.env.DB.batch(keys.map(k=>c.env.DB.prepare('DELETE FROM auth_rate_limits WHERE key=?').bind(k)))}
async function rateLimit(c:any,key:string,max:number,windowMs:number,blockMs=windowMs){const now=Date.now();const row:any=await c.env.DB.prepare('SELECT window_start,count,blocked_until FROM auth_rate_limits WHERE key=?').bind(key).first();if(row?.blocked_until&&Number(row.blocked_until)>now)return false;const start=Number(row?.window_start||0);if(!row||now-start>=windowMs){await c.env.DB.prepare('INSERT INTO auth_rate_limits(key,window_start,count,blocked_until) VALUES(?,?,1,0) ON CONFLICT(key) DO UPDATE SET window_start=excluded.window_start,count=1,blocked_until=0').bind(key,now).run();return true}const count=Number(row.count||0)+1;const blocked=count>max;await c.env.DB.prepare('UPDATE auth_rate_limits SET count=?,blocked_until=? WHERE key=?').bind(count,blocked?now+blockMs:0,key).run();return !blocked}
function setupOwnerEmails(env:Env){return String(env.ADMIN_OWNER_EMAIL||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)}
async function storageUsed(c:any){const used:any=await c.env.DB.prepare('SELECT COALESCE(SUM(bytes),0) bytes FROM photos WHERE r2_key IS NOT NULL').first();return Number(used?.bytes||0)}
async function reserveStorage(c:any,id:string,bytes:number){if(!c.env.MEDIA)return true;const used=await storageUsed(c);const r=await c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=reserved_bytes+? WHERE id=1 AND reserved_bytes+?+?<=?').bind(bytes,bytes,used,STORAGE_LIMIT_BYTES).run();if(Number(r.meta?.changes||0)!==1)return false;try{await c.env.DB.prepare('INSERT INTO storage_reservations(id,bytes,expires_at) VALUES(?,?,?)').bind(id,bytes,Date.now()+20*60*1000).run();return true}catch(e){await c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes).run();throw e}}
async function releaseStorage(c:any,id:string){const row:any=await c.env.DB.prepare('SELECT bytes FROM storage_reservations WHERE id=?').bind(id).first();if(!row)return;await c.env.DB.batch([c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(id),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(Number(row.bytes||0))])}
async function finalizeStorage(c:any,id:string){return releaseStorage(c,id)}

function normalizeInstagramHashtag(value:string){return String(value||'').trim().replace(/^#+/,'').toLowerCase()}
function captionHashtags(caption:string){return(caption.match(/#[\p{L}0-9_-]+/gu)||[]).map(normalizeInstagramHashtag)}
function matchedCategories(caption:string,serviceRows:any[],aliasRows:any[]=[]):string[]{const tags=captionHashtags(caption);if(!tags.length)return [];const serviceMatches=new Set<string>();for(const row of serviceRows){const aliases=String(row.instagram_hashtags||'').split(/[,\n]+/).map(normalizeInstagramHashtag).filter(Boolean);if(aliases.some(alias=>alias&&tags.some(tag=>tag.includes(alias))))serviceMatches.add(String(row.title))}for(const row of aliasRows){const alias=normalizeInstagramHashtag(String(row.hashtag||''));if(alias&&tags.some(tag=>tag.includes(alias)))serviceMatches.add(String(row.category))}if(serviceMatches.size)return Array.from(serviceMatches);const legacy:[string,string[]][]=[['Beach',['beach']],['Birthday',['birthday']],['Family',['family']],['Maternity',['maternity']],['Portfolio',['portfolio']],['Pre-Wedding',['prewedding']],['Wedding',['wedding']]];const legacyMatches=new Set<string>();for(const [name,aliases] of legacy){if(aliases.some(alias=>tags.some(tag=>tag.includes(alias))))legacyMatches.add(name)}return Array.from(legacyMatches)}
function instagramCategory(caption:string,serviceRows:any[]){const m=matchedCategories(caption,serviceRows);return m[0]||'Other'}
function unmatchedHashtags(caption:string,serviceRows:any[],aliasRows:any[]=[]):string[]{const tags=captionHashtags(caption);if(!tags.length)return [];const known=new Set<string>();for(const row of serviceRows){for(const a of String(row.instagram_hashtags||'').split(/[,\n]+/).map(normalizeInstagramHashtag).filter(Boolean))known.add(a)}for(const row of aliasRows){const alias=normalizeInstagramHashtag(String(row.hashtag||''));if(alias)known.add(alias)}for(const a of ['beach','birthday','family','maternity','portfolio','prewedding','wedding'])known.add(a);const knownList=Array.from(known);return Array.from(new Set(tags.filter(tag=>tag&&!knownList.some(alias=>alias&&tag.includes(alias)))))}
async function ensureCategoryAliasSchema(c:any){await c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS category_hashtag_aliases (hashtag TEXT PRIMARY KEY,category TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run()}
async function ensureHashtagSightingsSchema(c:any){await c.env.DB.batch([c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS hashtag_sightings (hashtag TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 1,last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sample_caption TEXT DEFAULT '',dismissed INTEGER NOT NULL DEFAULT 0)`)])}
async function requireAuth(c:any,next:any){const a=await session(c,c.env);if(!a)return c.json({error:'Unauthorized'},401);c.set('admin',a);await next()}
async function instagramAuthorize(c:any){if(!c.env.INSTAGRAM_APP_ID)return c.text('Instagram connection is not configured on this Worker.',500);const state=uid();const sig=await hmac(c.env,state);setCookie(c,'ig_oauth_state',`${state}.${sig}`,{httpOnly:true,secure:true,sameSite:'Lax',path:'/api/instagram',maxAge:600});const u=new URL('https://www.instagram.com/oauth/authorize');u.searchParams.set('force_reauth','true');u.searchParams.set('client_id',c.env.INSTAGRAM_APP_ID);u.searchParams.set('redirect_uri',await instagramRedirect(c));u.searchParams.set('response_type','code');u.searchParams.set('scope','instagram_business_basic');u.searchParams.set('state',state);return c.redirect(u.toString(),302)}
app.get('/api/instagram/connect',requireAuth,async c=>instagramAuthorize(c));
app.post('/api/admin/instagram/connect-link',requireAuth,async c=>{if(!c.env.INSTAGRAM_APP_ID||!c.env.INSTAGRAM_APP_SECRET)return c.json({error:'Instagram app credentials are not configured on this Worker.'},500);const raw=b64u(crypto.getRandomValues(new Uint8Array(32)));const tokenHash=await sha256(raw);const expiresAt=Date.now()+30*60*1000;await c.env.DB.prepare('DELETE FROM instagram_connection_links WHERE expires_at<=? OR used_at IS NOT NULL').bind(Date.now()).run();await c.env.DB.prepare('INSERT INTO instagram_connection_links(token_hash,expires_at) VALUES(?,?)').bind(tokenHash,expiresAt).run();const url=new URL(`/api/instagram/connect-link/${raw}`,c.req.url).toString();return c.json({ok:true,url,expiresAt});});
app.get('/api/instagram/connect-link/:token',async c=>{const token=c.req.param('token');if(!/^[A-Za-z0-9_-]{40,60}$/.test(token))return c.text('Invalid connection link.',400);const row:any=await c.env.DB.prepare('SELECT expires_at,used_at FROM instagram_connection_links WHERE token_hash=?').bind(await sha256(token)).first();if(!row||row.used_at||Number(row.expires_at)<=Date.now())return c.html('<h2>Connection link expired</h2><p>Please ask the photographer to create a new Instagram connection link.</p>',410);return c.html(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connect Instagram · Impression Photography</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080c0f;color:#f5f7f8;font-family:Arial,sans-serif}.card{width:min(460px,88vw);padding:32px;border:1px solid #273137;border-radius:20px;background:#11181d;text-align:center}.eyebrow{color:#e5c38d;font-size:11px;letter-spacing:.2em;font-weight:800}.card h1{font:600 36px Georgia,serif;margin:12px 0}.card p{color:#9da8ae;line-height:1.6}.btn{display:inline-block;margin-top:12px;padding:13px 20px;border-radius:999px;background:#f5f7f8;color:#080c0f;text-decoration:none;font-weight:700;border:0;cursor:pointer}</style></head><body><main class="card"><div class="eyebrow">IMPRESSION PHOTOGRAPHY</div><h1>Connect Instagram</h1><p>This secure link lets you authorize the photography website to access your Instagram media. You will log in to Instagram yourself. Your password is never shared with the photographer.</p><form method="post" action="/api/instagram/connect-link/${token}/start" target="_blank" rel="noopener noreferrer"><button class="btn" type="submit">Continue in Browser</button></form><p>This link expires in 30 minutes and is consumed only after Instagram is connected successfully. Instagram will open in a new browser tab so you can complete the authorization on the web. If you cancel or go back, you can try again with the same link while it is still valid.</p></main></body></html>`)});
app.post('/api/instagram/connect-link/:token/start',async c=>{const token=c.req.param('token');if(!/^[A-Za-z0-9_-]{40,60}$/.test(token))return c.text('Invalid connection link.',400);const now=Date.now();const row:any=await c.env.DB.prepare('SELECT expires_at,used_at FROM instagram_connection_links WHERE token_hash=?').bind(await sha256(token)).first();if(!row||row.used_at||Number(row.expires_at)<=now)return c.html('<h2>Connection link expired</h2><p>Please ask the photographer to create a new Instagram connection link.</p>',410);setCookie(c,'ig_connect_token',token,{httpOnly:true,secure:true,sameSite:'Lax',path:'/api/instagram',maxAge:600});return instagramAuthorize(c)});
app.get('/api/instagram/callback',async c=>{const err=c.req.query('error');const connectToken=getCookie(c,'ig_connect_token');if(err)return c.html(`<h2>Instagram connection cancelled</h2><p>The connection was not completed, so your invitation link is still valid.</p><p>You can close this window and use the same link again while it is within its 30-minute validity period.</p>`);let code=c.req.query('code');if(code)code=code.replace(/#_$/,'').replace(/%23_$/i,'').trim();const state=c.req.query('state');const saved=getCookie(c,'ig_oauth_state');deleteCookie(c,'ig_oauth_state',{path:'/api/instagram'});if(!code)return c.text('Instagram did not return an authorization code.',400);if(!state||!saved){return c.text('Instagram connection state is missing. Please start again from the connection link.',400)}const [savedState,savedSig]=saved.split('.');if(state!==savedState||savedSig!==await hmac(c.env,state))return c.text('Instagram connection state could not be verified. Please start again.',400);if(!c.env.INSTAGRAM_APP_ID||!c.env.INSTAGRAM_APP_SECRET)return c.text('Instagram app credentials are not configured on this Worker.',500);const redirectUri=await instagramRedirect(c);try{const shortResp=await fetch('https://api.instagram.com/oauth/access_token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:c.env.INSTAGRAM_APP_ID,client_secret:c.env.INSTAGRAM_APP_SECRET,grant_type:'authorization_code',redirect_uri:redirectUri,code})});const short:any=await shortResp.json();if(!shortResp.ok||!short.access_token)throw new Error(short?.error_message||short?.error?.message||'Instagram token exchange failed');const longUrl=new URL('https://graph.instagram.com/access_token');longUrl.searchParams.set('grant_type','ig_exchange_token');longUrl.searchParams.set('client_secret',c.env.INSTAGRAM_APP_SECRET);longUrl.searchParams.set('access_token',short.access_token);const longResp=await fetch(longUrl);const long:any=await longResp.json();if(!longResp.ok||!long.access_token)throw new Error(long?.error?.message||long?.error_message||'Instagram long-lived token exchange failed');const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';const meUrl=new URL(`https://graph.instagram.com/${version}/me`);meUrl.searchParams.set('fields','id,username');meUrl.searchParams.set('access_token',long.access_token);const meResp=await fetch(meUrl);const me:any=await meResp.json();if(!meResp.ok||!me.id)throw new Error(me?.error?.message||'Could not read the connected Instagram account');const expiresAt=Date.now()+Number(long.expires_in||5184000)*1000;await c.env.DB.prepare(`INSERT INTO instagram_integrations(provider,user_id,username,access_token_enc,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(provider) DO UPDATE SET user_id=excluded.user_id,username=excluded.username,access_token_enc=excluded.access_token_enc,expires_at=excluded.expires_at,updated_at=CURRENT_TIMESTAMP`).bind('instagram',String(me.id),String(me.username||''),await encryptToken(c.env,String(long.access_token)),expiresAt).run();if(connectToken){const consumed:any=await c.env.DB.prepare('UPDATE instagram_connection_links SET used_at=? WHERE token_hash=? AND used_at IS NULL AND expires_at>?').bind(Date.now(),await sha256(connectToken),Date.now()).run();if(Number(consumed.meta?.changes||0)!==1){console.error('INSTAGRAM_CONNECT_LINK_CONSUME_FAILED')}}deleteCookie(c,'ig_connect_token',{path:'/api/instagram'});return c.html(`<h2>Instagram connected successfully</h2><p>Connected account: <strong>${String(me.username||me.id).replace(/[<>]/g,'')}</strong></p><p>You can close this window and return to the website.</p>`)}catch(e:any){console.error('INSTAGRAM_OAUTH_ERROR',e?.name||'Error',e?.message||String(e));return c.html(`<h2>Instagram connection failed</h2><p>We could not complete the Instagram connection. Please start again.</p><p>You can close this window and return to the website.</p>`,500)}});
app.get('/api/instagram/status',requireAuth,async c=>{const conn=await getInstagramConnection(c);return c.json({connected:Boolean(conn),username:conn?.username||null})});
function pickGallerySlotGroups(slots:any[],published:any[]):({photos:any[]}|null)[]{const groupKey=(p:any)=>String(p?.group_id||p?.id);const autoPool=published.filter(p=>!p.excluded_from_auto);const groups=new Map<string,any[]>();for(const p of autoPool){const key=groupKey(p);if(!groups.has(key))groups.set(key,[]);groups.get(key)!.push(p)}for(const list of groups.values())list.sort((a,b)=>Number(a.group_order||0)-Number(b.group_order||0));const rep=(key:string)=>groups.get(key)!.slice().sort((a,b)=>Number(b.total_score||0)-Number(a.total_score||0))[0];const byCategory=new Map<string,string[]>();for(const key of groups.keys()){const cat=String(rep(key).category||rep(key).occasion||'Other');if(!byCategory.has(cat))byCategory.set(cat,[]);byCategory.get(cat)!.push(key)}for(const list of byCategory.values())list.sort((a,b)=>Number(rep(b).total_score||0)-Number(rep(a).total_score||0));const allSortedKeys=[...groups.keys()].sort((a,b)=>Number(rep(b).total_score||0)-Number(rep(a).total_score||0));const byId=new Map(published.map(p=>[String(p.id),p]));const dayBucket=Math.floor(Date.now()/86400000);const used=new Set<string>();const result:({photos:any[]}|null)[]=[];for(const slot of(slots||[])){if(slot?.type==='pinned'){const p=byId.get(String(slot.photo_id));if(p&&!used.has(groupKey(p))){const key=groupKey(p);used.add(key);result.push({photos:groups.get(key)||[p]})}else result.push(null);continue}const cat=String(slot?.category||'Other');let pool=(byCategory.get(cat)||[]).filter(k=>!used.has(k));if(!pool.length)pool=allSortedKeys.filter(k=>!used.has(k));if(!pool.length){result.push(null);continue}const topN=pool.slice(0,Math.min(5,pool.length));const pickKey=topN[dayBucket%topN.length];used.add(pickKey);result.push({photos:groups.get(pickKey)||[]})}return result}
function resolveGallerySlots(slots:any[],published:any[]):any[]{return pickGallerySlotGroups(slots,published).flatMap(g=>g?g.photos:[])}
function resolveGallerySlotsAligned(slots:any[],published:any[]):any[]{return pickGallerySlotGroups(slots,published).map(g=>g?g.photos[0]:null)}
async function ensureInterimTestimonialsTable(c:any){await c.env.DB.prepare('CREATE TABLE IF NOT EXISTS testimonials (id TEXT PRIMARY KEY,source TEXT NOT NULL DEFAULT \'manual\',author_name TEXT NOT NULL,rating INTEGER NOT NULL DEFAULT 5,review_text TEXT NOT NULL DEFAULT \'\',relative_time TEXT DEFAULT \'\',verified INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,image_url TEXT DEFAULT \'\',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)').run()}
async function getInterimTestimonials(c:any,googleError?:boolean){await ensureInterimTestimonialsTable(c);const rows:any=await c.env.DB.prepare('SELECT id,author_name,rating,review_text,relative_time,verified,image_url FROM testimonials WHERE active=1 ORDER BY sort_order,created_at DESC LIMIT 8').all();const reviews=rows.results||[];if(!reviews.length)return{configured:false,aggregate:null,reviews:[],googleError:!!googleError};const agg:any=await c.env.DB.prepare('SELECT AVG(rating) avgr,COUNT(*) n FROM testimonials WHERE active=1').first();return{configured:false,aggregate:{rating:Math.round(Number(agg?.avgr||5)*10)/10,count:Number(agg?.n||reviews.length),source_label:'Based on Google Reviews',source:'interim'},reviews,googleError:!!googleError}}
const FESTIVAL_COPY:Record<string,{kicker:string,title:string,copy:string,accent:string}>={ganesh:{kicker:'WISHING YOU',title:'Happy Ganesh Chaturthi!',copy:'May Lord Ganesha bless you and your family with happiness, prosperity and safe journeys.',accent:'#e07b1f'},diwali:{kicker:'WISHING YOU',title:'Happy Diwali!',copy:'May the festival of lights fill your home with happiness, peace and prosperity. Wishing you a joyful Diwali.',accent:'#c9a15f'},christmas:{kicker:'WISHING YOU',title:'Merry Christmas!',copy:'May the joy of this season fill your heart with love, peace and happiness. Wishing you and your family a wonderful Christmas.',accent:'#e2544f'},eid:{kicker:'WISHING YOU',title:'Eid Mubarak!',copy:'Wishing you and your family peace, happiness and good health this Eid.',accent:'#4fb37e'},newyear:{kicker:'WISHING YOU',title:'Happy New Year!',copy:'May the new year bring new beginnings, happiness and many wonderful moments. Here\u2019s to a great year ahead.',accent:'#c9a15f'},independence:{kicker:'WISHING YOU',title:'Happy Independence Day!',copy:'Wishing everyone a proud and meaningful Independence Day.',accent:'#e07b1f'},anniversary:{kicker:'WISHING YOU',title:'Celebrating Another Year!',copy:'Today marks another year of Impression Photography \u2014 thank you to every couple and family who trusted us with your moments. Here\u2019s to many more.',accent:'#c9a15f'}};
const FOUNDING_YEAR=2021;
function ordinal(n:number):string{const j=n%10,k=n%100;if(j===1&&k!==11)return n+'st';if(j===2&&k!==12)return n+'nd';if(j===3&&k!==13)return n+'rd';return n+'th'}
function anniversaryCopy(now:Date=istNow()){const years=now.getUTCFullYear()-FOUNDING_YEAR;return{kicker:'WISHING YOU',title:`Happy ${ordinal(years)} Anniversary!`,copy:`Today marks ${years} years of Impression Photography \u2014 thank you to every couple and family who trusted us with your moments. Here's to many more.`,accent:'#c9a15f'}}
function festivalCopyFor(key:string):{kicker:string,title:string,copy:string,accent:string}{return key==='anniversary'?anniversaryCopy():FESTIVAL_COPY[key]}
function istNow():Date{return new Date(Date.now()+5.5*3600000)}
const DEFAULT_FESTIVAL_DATES:Record<string,{start:string,end:string}>={ganesh:{start:'2026-09-14',end:'2026-09-16'},diwali:{start:'2026-11-06',end:'2026-11-10'},eid:{start:'2026-03-20',end:'2026-03-22'}};
function getActiveFestivalKey(now:Date=istNow(),movableDates:Record<string,{start?:string,end?:string}> = {}):string|null{const y=now.getUTCFullYear(),m=now.getUTCMonth()+1,d=now.getUTCDate();const key=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
  if(m===1&&d<=2)return 'newyear';
  if(m===8&&d===15)return 'independence';
  if(m===9&&d===5)return 'anniversary';
  if(m===12&&d>=24&&d<=26)return 'christmas';
  for(const k of ['ganesh','diwali','eid']){const range=movableDates[k]||DEFAULT_FESTIVAL_DATES[k];if(range?.start&&range?.end&&key>=range.start&&key<=range.end)return k}
  return null}
async function fetchGoogleReviews(c:any){const key=c.env.GOOGLE_PLACES_API_KEY,placeId=c.env.GOOGLE_PLACE_ID;if(!key||!placeId)return await getInterimTestimonials(c,false);const cache=(caches as any).default;const cacheKey=new Request(`https://cache.internal/google-reviews/${encodeURIComponent(placeId)}`);const cached=await cache.match(cacheKey);if(cached)return await cached.json();try{const url=`https://places.googleapis.com/v1/places/${encodeURIComponent(placeId)}?languageCode=en`;const r=await fetch(url,{headers:{'X-Goog-Api-Key':key,'X-Goog-FieldMask':'rating,userRatingCount,reviews,displayName,googleMapsUri'}});if(!r.ok)return await getInterimTestimonials(c,true);const data:any=await r.json();const reviews=(data.reviews||[]).slice(0,5).map((rv:any)=>({id:rv.name||uid(),author_name:rv.authorAttribution?.displayName||'Google user',rating:Math.round(Number(rv.rating||5)),review_text:rv.text?.text||rv.originalText?.text||'',relative_time:rv.relativePublishTimeDescription||'',verified:true,image_url:''}));const result={configured:true,aggregate:{rating:Number(data.rating||0),count:Number(data.userRatingCount||0),source_label:'Google Reviews',source:'google_live'},reviews,mapsUri:data.googleMapsUri||null};const resp=new Response(JSON.stringify(result),{headers:{'Content-Type':'application/json','Cache-Control':'max-age=600'}});c.executionCtx?.waitUntil?.(cache.put(cacheKey,resp.clone()));return result}catch(e){return await getInterimTestimonials(c,true)}}
app.get('/api/public',async c=>{await ensureV3Schema(c);const [s,v,p,settings,careers,googleReviews]=await Promise.all([c.env.DB.prepare('SELECT id,title,description,image_url,active,sort_order,instagram_hashtags FROM services WHERE active=1 ORDER BY sort_order,id').all(),c.env.DB.prepare("SELECT * FROM videos WHERE active=1 AND platform IN ('youtube','instagram') ORDER BY sort_order,id").all(),c.env.DB.prepare("SELECT id,source,source_id,image_url,caption,occasion,category,created_at,group_id,group_order,total_score,focal_x,focal_y,focal_zoom,focal_x_mobile,focal_y_mobile,focal_zoom_mobile,focal_x_hero,focal_y_hero,focal_zoom_hero,focal_x_hero_mobile,focal_y_hero_mobile,focal_zoom_hero_mobile,excluded_from_auto FROM photos WHERE published=1 ORDER BY created_at DESC LIMIT 300").all(),c.env.DB.prepare('SELECT key,value FROM site_settings').all(),c.env.DB.prepare("SELECT id,title,requirements,description,salary_disclosed,salary_text,duration,valid_until,google_form_url,sort_order FROM careers WHERE active=1 AND (valid_until IS NULL OR valid_until='' OR valid_until>=date('now')) ORDER BY sort_order,id").all(),fetchGoogleReviews(c)]);const cfg:any={};for(const row of(settings.results||[])){try{cfg[row.key]=JSON.parse(row.value)}catch{cfg[row.key]=row.value}}const published=(p.results||[]) as any[];const byId=new Map(published.map(x=>[String(x.id),x]));const resolve=(ids:any[])=>ids.map(id=>byId.get(String(id))).filter(Boolean);const heroCfg=cfg.hero_config?{count:4,source:'latest_instagram',photo_ids:[],interval:7,transition:'normal',scrollReveal:false,...cfg.hero_config}:{count:4,source:'latest_instagram',photo_ids:[],interval:7,transition:'normal',scrollReveal:false};const galleryCfg=cfg.gallery_config||JSON.parse(DEFAULT_GALLERY_CONFIG);const stripPhotos=resolve((cfg.strip_config?.photo_ids||[]));const stripIds=new Set(stripPhotos.map((x:any)=>String(x.id)));const latestInstagram=published.filter(x=>String(x.source||'').toLowerCase()==='instagram'&&!x.excluded_from_auto&&!stripIds.has(String(x.id))).slice(0,Number(heroCfg.count||4));const aboutCfg={photo_id:null,text:DEFAULT_ABOUT_TEXT,...(cfg.about_config||{})};const aboutPhoto=aboutCfg.photo_id?byId.get(String(aboutCfg.photo_id))||null:null;const activeFestivalKey=getActiveFestivalKey(istNow(),(cfg.festival_config||{}).dates||{});let festival=null;if(activeFestivalKey)festival={key:activeFestivalKey,...festivalCopyFor(activeFestivalKey),scrollReveal:activeFestivalKey==='anniversary'&&!!(cfg.festival_config||{}).anniversaryScrollReveal,photo:{image_url:FESTIVAL_IMAGE_PATHS[activeFestivalKey],image_url_mobile:FESTIVAL_IMAGE_PATHS_MOBILE[activeFestivalKey]||FESTIVAL_IMAGE_PATHS[activeFestivalKey],focal_x:50,focal_y:50}};return c.json({services:s.results,videos:v.results,careers:careers.results||[],photos:published,phone:c.env.PHONE,maps:c.env.MAPS_URL,testimonials:googleReviews.reviews||[],reviewsAggregate:googleReviews.aggregate||null,festival,homepage:{hero:heroCfg,gallery:galleryCfg,strip:cfg.strip_config?{interval:7,transition:'normal',reveal:'none',...cfg.strip_config}:null,about:aboutCfg,heroPhotos:heroCfg.source==='manual'?resolve(heroCfg.photo_ids||[]):latestInstagram,galleryPhotos:resolveGallerySlots(galleryCfg.slots||[],published),stripPhotos,aboutPhoto}});});
