async function sha256(value:string){const d=await crypto.subtle.digest('SHA-256',enc.encode(value));return b64u(d)}
async function setupSignature(id:string,env:Env){return hmac(env,`setup:${id}`)}
function emailWrapper(bodyHtml:string){return `<div style="background:#f5f1e8;padding:32px 16px;font-family:Arial,sans-serif"><div style="max-width:520px;margin:auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e5ddd0"><div style="background:#14181b;padding:26px 32px;text-align:center"><img src="https://impressionphotographygoa.com/impression-logo.webp" alt="Impression Photography" width="40" height="40" style="display:block;margin:0 auto 10px"/><div style="color:#ffffff;font-family:Georgia,'Times New Roman',serif;font-size:14px;letter-spacing:3px;text-transform:uppercase">Impression Photography</div></div><div style="padding:32px;color:#2b2f33;font-size:15px;line-height:1.6">${bodyHtml}</div><div style="padding:16px 32px;background:#f8f5ef;color:#8a8478;font-size:12px;text-align:center">Impression Photography · Candolim, Goa</div></div></div>`}
async function sendSetupCode(c:any,email:string,code:string){
  if(!c.env.RESEND_API_KEY||!c.env.RESEND_FROM_EMAIL)throw new Error('Email verification is not configured. Add RESEND_API_KEY and RESEND_FROM_EMAIL to the Worker.');
  const body=emailWrapper(`<h2 style="margin:0 0 6px;font-family:Georgia,serif;font-size:20px;color:#14181b">Verify your email</h2><p style="margin:0 0 18px;color:#5b6167">Use this code to create the Owner account for your private admin area.</p><div style="text-align:center;margin:24px 0"><span style="display:inline-block;background:#f5f1e8;border:1px solid #e5ddd0;border-radius:10px;padding:14px 28px;font-size:30px;font-weight:700;letter-spacing:10px;color:#14181b">${code}</span></div><p style="margin:0;color:#8a8478;font-size:13px">This code expires in 10 minutes. If you didn't request this, you can safely ignore this email.</p>`);
  const resp=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${c.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:c.env.RESEND_FROM_EMAIL,to:[email],subject:'Your Impression Photography verification code',html:body})});
  if(!resp.ok){const detail=await resp.text().catch(()=> '');throw new Error(detail||'Could not send verification email')}
}
async function sendAdminInvitation(c:any,email:string,url:string){
  if(!c.env.RESEND_API_KEY||!c.env.RESEND_FROM_EMAIL)throw new Error('Email invitations are not configured. Add RESEND_API_KEY and RESEND_FROM_EMAIL to the Worker.');
  const body=emailWrapper(`<h2 style="margin:0 0 6px;font-family:Georgia,serif;font-size:20px;color:#14181b">You're invited</h2><p style="margin:0 0 22px;color:#5b6167">You've been invited to join the Impression Photography admin team. Click below to verify your email and set your own password.</p><div style="text-align:center;margin:26px 0"><a href="${url}" style="display:inline-block;background:#14181b;color:#ffffff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px;letter-spacing:.5px">Verify email &amp; create account</a></div><p style="margin:0;color:#8a8478;font-size:13px">This invitation expires in 12 hours. If you didn't expect this, you can safely ignore this email.</p>`);
  const payload={from:c.env.RESEND_FROM_EMAIL,to:[email],subject:"You've been invited to Impression Photography Admin",html:body};
  for(let attempt=0;attempt<3;attempt++){const resp=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${c.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify(payload)});if(resp.ok)return;const detail=await resp.text().catch(()=> '');if(resp.status!==429||attempt===2)throw new Error(detail||'Could not send invitation email');const retry=Number(resp.headers.get('retry-after')||'1');await new Promise(r=>setTimeout(r,Math.min(3000,Math.max(500,retry*1000))));}
}
