app.post('/api/setup/request-code',async c=>{const exists=await c.env.DB.prepare('SELECT id FROM admins LIMIT 1').first();if(exists)return c.json({error:'Setup already completed'},409);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const email=String(b.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return c.json({error:'Enter a valid email address'},400);if(!setupOwnerEmails(c.env).includes(email))return c.json({error:'This email is not authorized to initialize the Owner account.'},403);if(!c.env.RESEND_API_KEY||!c.env.RESEND_FROM_EMAIL)return c.json({error:'Email verification is not configured yet'},503);const ip=clientIp(c);if(!(await rateLimit(c,`setup-ip:${ip}`,5,60*60*1000,60*60*1000))||!(await rateLimit(c,`setup-email:${email}`,3,60*60*1000,60*60*1000))||!(await rateLimit(c,'setup-global',20,60*60*1000,60*60*1000)))return c.json({error:'Too many setup requests. Please try again later.'},429);const recent:any=await c.env.DB.prepare('SELECT created_at FROM setup_verifications WHERE email=? ORDER BY created_at DESC LIMIT 1').bind(email).first();if(recent&&Date.now()-Date.parse(String(recent.created_at))<60000)return c.json({error:'Please wait a minute before requesting another code'},429);const random=new Uint32Array(1);crypto.getRandomValues(random);const code=String(100000+(random[0]%900000));const id=uid();const expiresAt=Date.now()+10*60*1000;await c.env.DB.prepare('INSERT INTO setup_verifications(id,email,code_hash,expires_at,attempts) VALUES(?,?,?,?,0)').bind(id,email,await sha256(`${email}:${code}`),expiresAt).run();try{await sendSetupCode(c,email,code)}catch(e:any){await c.env.DB.prepare('DELETE FROM setup_verifications WHERE id=?').bind(id).run();return c.json({error:e?.message||'Could not send verification email'},502)}return c.json({ok:true});});
app.post('/api/setup/verify-code',async c=>{const exists=await c.env.DB.prepare('SELECT id FROM admins LIMIT 1').first();if(exists)return c.json({error:'Setup already completed'},409);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const email=String(b.email||'').trim().toLowerCase(),code=String(b.code||'').trim();if(!setupOwnerEmails(c.env).includes(email))return c.json({error:'This email is not authorized to initialize the Owner account.'},403);if(!email||!/^[0-9]{6}$/.test(code))return c.json({error:'Enter the 6-digit verification code'},400);if(!(await rateLimit(c,`verify-ip:${clientIp(c)}`,15,15*60*1000,15*60*1000))||!(await rateLimit(c,`verify-email:${email}`,10,15*60*1000,15*60*1000)))return c.json({error:'Too many verification attempts. Please try again later.'},429);const row:any=await c.env.DB.prepare('SELECT * FROM setup_verifications WHERE email=? AND used_at IS NULL ORDER BY created_at DESC LIMIT 1').bind(email).first();if(!row)return c.json({error:'Verification code not found. Request a new code.'},400);if(Number(row.expires_at)<Date.now())return c.json({error:'That code has expired. Request a new code.'},400);if(Number(row.attempts)>=5)return c.json({error:'Too many incorrect attempts. Request a new code.'},429);await c.env.DB.prepare('UPDATE setup_verifications SET attempts=attempts+1 WHERE id=?').bind(row.id).run();if(await sha256(`${email}:${code}`)!==row.code_hash)return c.json({error:'Incorrect verification code'},400);await c.env.DB.prepare('UPDATE setup_verifications SET verified_at=? WHERE id=?').bind(Date.now(),row.id).run();const sig=await setupSignature(row.id,c.env);setCookie(c,'ip_setup_verified',`${row.id}.${sig}`,{httpOnly:true,secure:true,sameSite:'Strict',path:'/api/setup',maxAge:900});return c.json({ok:true});});
app.post('/api/setup/create',async c=>{const exists=await c.env.DB.prepare('SELECT id FROM admins LIMIT 1').first();if(exists)return c.json({error:'Setup already completed'},409);const cookie=getCookie(c,'ip_setup_verified');if(!cookie)return c.json({error:'Verify your email first'},403);const [id,sig]=cookie.split('.');if(!id||!sig||sig!==await setupSignature(id,c.env))return c.json({error:'Verification expired. Start again.'},403);const row:any=await c.env.DB.prepare('SELECT * FROM setup_verifications WHERE id=? AND used_at IS NULL').bind(id).first();if(!row||!row.verified_at||Date.now()-Number(row.verified_at)>15*60*1000||!setupOwnerEmails(c.env).includes(String(row.email).toLowerCase()))return c.json({error:'Verification expired. Start again.'},403);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const name=String(b.name||'').trim(),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||''),confirm=String(b.confirmPassword||'');if(!name||!email||!password||!confirm)return c.json({error:'All fields are required'},400);if(email!==row.email)return c.json({error:'Verified email does not match'},400);if(password!==confirm)return c.json({error:'Passwords do not match'},400);if(password.length<12)return c.json({error:'Password must be at least 12 characters'},400);const adminId=uid();try{const passwordHash=await hashPassword(password);const result=await c.env.DB.batch([c.env.DB.prepare('INSERT INTO admins(id,name,email,password_hash,role) VALUES(?,?,?,?,?)').bind(adminId,name,email,passwordHash,'owner'),c.env.DB.prepare('UPDATE setup_verifications SET used_at=? WHERE id=?').bind(Date.now(),id)]);if(result.some((r:any)=>r?.success===false))throw new Error('Database batch returned an unsuccessful statement');}catch(e:any){console.error('OWNER_CREATE_ERROR',e?.name||'Error',e?.message||String(e));return c.json({error:'Owner account could not be created. Please try again.'},500)}deleteCookie(c,'ip_setup_verified',{path:'/api/setup'});return c.json({ok:true});});
app.post('/api/login',async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const email=String(b.email||'').trim().toLowerCase();const password=String(b.password||'');if(!email||!password)return c.json({error:'Email and password are required'},400);const ip=clientIp(c);const ipOk=await rateLimit(c,`login-ip:${ip}`,20,15*60*1000,15*60*1000);const emailOk=await rateLimit(c,`login-email:${email}`,5,15*60*1000,15*60*1000);if(!ipOk||!emailOk)return c.json({error:'Too many sign-in attempts. Please try again later.'},429);const a:any=await c.env.DB.prepare('SELECT * FROM admins WHERE email=? AND active=1').bind(email).first();const valid=Boolean(a&&await verifyPassword(password,a.password_hash));if(!valid)return c.json({error:'Invalid credentials'},401);await clearRateLimit(c,`login-ip:${ip}`,`login-email:${email}`);if(Number(String(a.password_hash).split('$')[1]||0)<PASSWORD_ITERATIONS){try{await c.env.DB.prepare('UPDATE admins SET password_hash=? WHERE id=?').bind(await hashPassword(password),a.id).run()}catch(e){console.error('PASSWORD_UPGRADE_ERROR',e?.name||'Error',e?.message||String(e))}}const id=uid();const exp=Date.now()+1000*60*60*12;await c.env.DB.prepare('INSERT INTO sessions(id,admin_id,expires_at) VALUES(?,?,?)').bind(id,a.id,exp).run();const sig=await hmac(c.env,id);setCookie(c,'ip_session',id,{httpOnly:true,secure:true,sameSite:'Strict',path:'/',maxAge:43200});setCookie(c,'ip_sig',sig,{httpOnly:true,secure:true,sameSite:'Strict',path:'/',maxAge:43200});await logActivity(c,a.id,a.name||a.email,'Logged in');return c.json({id:a.id,name:a.name,email:a.email,role:a.role});});
