app.post('/api/admin/photos',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=uid();const bytes=finiteNumber(b.bytes,0,30*1024*1024,0);if(bytes<0)return c.json({error:'Invalid file size'},400);const caption=textField(b.caption,2000),occasion=textField(b.occasion||b.category||'Other',100),category=textField(b.category||b.occasion||'Other',100);const status=['pending','approved','rejected'].includes(String(b.status||'pending'))?String(b.status||'pending'):'pending';if(String(b.caption||'').length>2000||String(b.category||b.occasion||'Other').length>100)return c.json({error:'Photo fields are too long'},400);const reservationId=String(b.reservation_id||'');if(b.r2_key&&!reservationId)return c.json({error:'R2-backed photos require a valid upload reservation'},400);if(reservationId){const reservation:any=await c.env.DB.prepare('SELECT * FROM storage_reservations WHERE id=?').bind(reservationId).first();if(!reservation||Number(reservation.bytes)!==bytes||Number(reservation.expires_at)<Date.now())return c.json({error:'Upload reservation expired. Please upload the photo again.'},409);if(b.r2_key!==reservation.key)return c.json({error:'Upload reservation does not match the photo'},400);try{await c.env.DB.batch([c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,sharpness,brightness,exposure,contrast,clarity,color,composition,similarity,total_score,phash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,b.source||'upload',b.source_id||null,b.r2_key,b.image_url,caption,occasion,category,status,b.published?1:0,b.width||null,b.height||null,bytes,b.sharpness||0,b.brightness||0,b.exposure||0,b.contrast||0,b.clarity||0,b.color||0,b.composition||0,b.similarity||0,b.total_score||0,b.phash||null),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes),c.env.DB.prepare('DELETE FROM upload_nonces WHERE reservation_id=?').bind(reservationId)]);return c.json({id})}catch(e){if(c.env.MEDIA&&reservation.key)await c.env.MEDIA.delete(reservation.key).catch(()=>{});await c.env.DB.batch([c.env.DB.prepare('DELETE FROM photos WHERE id=?').bind(id),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes),c.env.DB.prepare('DELETE FROM upload_nonces WHERE reservation_id=?').bind(reservationId)]).catch(()=>{});return c.json({error:'Photo record could not be created; the uploaded file was cleaned up.'},500)}}const used=await storageUsed(c);if(Number(used)+bytes>STORAGE_LIMIT_BYTES)return c.json({error:'5 GB storage limit reached'},413);await c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,sharpness,brightness,exposure,contrast,clarity,color,composition,similarity,total_score,phash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,b.source||'upload',b.source_id||null,b.r2_key||null,b.image_url||null,caption,occasion,category,status,b.published?1:0,b.width||null,b.height||null,bytes,b.sharpness||0,b.brightness||0,b.exposure||0,b.contrast||0,b.clarity||0,b.color||0,b.composition||0,b.similarity||0,b.total_score||0,b.phash||null).run();return c.json({id});});
app.post('/api/admin/upload-url',requireAuth,async c=>{if(!c.env.MEDIA)return c.json({error:'Photo storage is not enabled yet. Please connect R2 storage before uploading.'},503);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const size=Number(b.size||0);const contentType=String(b.contentType||'').toLowerCase();if(!Number.isInteger(size)||size<=0||size>30*1024*1024)return c.json({error:'File must be 1 byte–30 MB'},400);if(contentType!=='image/webp')return c.json({error:'Uploads must be converted to WebP first'},415);const reservationId=uid();if(!(await reserveStorage(c,reservationId,size)))return c.json({error:'5 GB storage limit reached'},413);const safe=String(b.name||'photo.webp').replace(/[^a-zA-Z0-9._-]/g,'_').replace(/\.[^.]+$/,'')+'.webp';const key=`photos/${new Date().toISOString().slice(0,10)}/${uid()}-${safe}`;const exp=Date.now()+600000;const nonce=uid();await c.env.DB.prepare('UPDATE storage_reservations SET key=? WHERE id=?').bind(key,reservationId).run();try{await c.env.DB.prepare('INSERT INTO upload_nonces(id,reservation_id,key,expected_size,content_type,expires_at,used_at) VALUES(?,?,?,?,?,?,NULL)').bind(nonce,reservationId,key,size,contentType,exp).run();}catch(e){await releaseStorage(c,reservationId);return c.json({error:'Could not prepare upload'},500)}const url=new URL(c.req.url);url.pathname=`/api/upload/${encodeURIComponent(key)}`;url.search=`?expires=${exp}&nonce=${encodeURIComponent(nonce)}`;const token=await hmac(c.env,`PUT:${key}:${size}:${contentType}:${exp}:${nonce}`);url.search+=`&token=${encodeURIComponent(token)}`;return c.json({key,url:url.toString(),expires:exp,reservationId});});
app.put('/api/upload/:key',async c=>{if(!c.env.MEDIA)return c.json({error:'Photo storage is not enabled yet.'},503);const key=decodeURIComponent(c.req.param('key'));const u=new URL(c.req.url);const token=u.searchParams.get('token')||'';const exp=Number(u.searchParams.get('expires')||0);const nonce=u.searchParams.get('nonce')||'';const row:any=await c.env.DB.prepare('SELECT * FROM upload_nonces WHERE id=? AND key=?').bind(nonce,key).first();if(!row||row.used_at||Number(row.expires_at)<Date.now())return c.json({error:'Upload URL expired or already used'},403);const contentType=(c.req.header('Content-Type')||'').toLowerCase();const expected=Number(row.expected_size||0);if(!key.toLowerCase().endsWith('.webp')||contentType!=='image/webp'||exp!==Number(row.expires_at)||token!==await hmac(c.env,`PUT:${key}:${expected}:${contentType}:${exp}:${nonce}`))return c.json({error:'Invalid upload authorization'},403);if(!c.req.raw.body)return c.json({error:'No body'},400);const buf=await c.req.raw.arrayBuffer();if(buf.byteLength!==expected||buf.byteLength>30*1024*1024)return c.json({error:'Uploaded file size does not match the signed request'},413);const claimed=await c.env.DB.prepare('UPDATE upload_nonces SET used_at=? WHERE id=? AND used_at IS NULL').bind(Date.now(),nonce).run();if(Number(claimed.meta?.changes||0)!==1)return c.json({error:'Upload URL already used'},409);try{await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.prepare('UPDATE upload_nonces SET uploaded_at=? WHERE id=?').bind(Date.now(),nonce).run();return c.json({ok:true,key,reservationId:row.reservation_id});}catch(e){await c.env.MEDIA.delete(key).catch(()=>{});await releaseStorage(c,row.reservation_id||'');return c.json({error:'Storage upload failed'},502)}});
function instagramImportedScore(item:any){const w=Number(item.width||0),h=Number(item.height||0),bytes=Number(item.bytes||0);const pixels=w*h;const resolution=Math.min(100,pixels?Math.sqrt(pixels)/25:55);const size=Math.min(100,bytes?Math.log10(bytes)/7*100:55);const ratio=w&&h?w/h:1.5;const framing=Math.max(0,100-Math.abs(ratio-1.5)*35);return resolution*.45+size*.25+framing*.2+10;}
async function syncInstagramData(c:any,startCursor?:string){
  let conn=await getInstagramConnection(c);
  if(!conn)return {ok:false,error:'Instagram is not connected. Open the Connect Instagram link first.',status:400};
  conn=await refreshInstagramToken(c,conn);
  await ensureInstagramReelIgnoreSchema(c);
  const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';
  let endpoint=startCursor||`https://graph.instagram.com/${version}/${encodeURIComponent(conn.user_id)}/media?fields=id,caption,media_type,media_product_type,media_url,thumbnail_url,permalink,timestamp,width,height,children{media_type,media_url,thumbnail_url,id}&limit=50&access_token=${encodeURIComponent(conn.access_token)}`;
  await ensureCategoryAliasSchema(c);
  const serviceRows:any[]=(await c.env.DB.prepare('SELECT title,instagram_hashtags FROM services WHERE active=1 ORDER BY sort_order,id').all()).results;
  const aliasRows:any[]=(await c.env.DB.prepare('SELECT hashtag,category FROM category_hashtag_aliases').all()).results||[];
  let photosImported=0,reelsImported=0,skipped=0,pages=0;
  while(endpoint&&pages<3){
    const resp=await fetch(endpoint);const data:any=await resp.json();
    if(!resp.ok)return {ok:false,error:data?.error?.message||'Instagram API request failed',status:502,photosImported,reelsImported,skipped};
    for(const item of(data.data||[])){
      const matched=matchedCategories(item.caption||'',serviceRows,aliasRows);
      const category=matched.length===1?matched[0]:'Other';
      const autoPublish=matched.length===1;
      if(!autoPublish){const missed=unmatchedHashtags(item.caption||'',serviceRows,aliasRows);if(missed.length){await ensureHashtagSightingsSchema(c);for(const tag of missed){await c.env.DB.prepare('INSERT INTO hashtag_sightings(hashtag,count,last_seen,sample_caption) VALUES(?,1,CURRENT_TIMESTAMP,?) ON CONFLICT(hashtag) DO UPDATE SET count=count+1,last_seen=CURRENT_TIMESTAMP').bind(tag,(item.caption||'').slice(0,200)).run()}}}
      const isReel=item.media_type==='VIDEO'&&(item.media_product_type==='REELS'||/\/reel\//i.test(item.permalink||''));
      if(isReel){
        const ignored=await c.env.DB.prepare('SELECT id FROM instagram_reel_ignores WHERE source_url=? OR video_id=? LIMIT 1').bind(item.permalink||'',item.id).first();
        if(ignored){skipped++;continue}
        const exists:any=await c.env.DB.prepare('SELECT id,thumbnail_url FROM videos WHERE source_url=?').bind(item.permalink||'').first();
        if(exists&&exists.thumbnail_url){skipped++;continue}
        let storedThumb=item.thumbnail_url||'';
        if(item.thumbnail_url&&c.env.MEDIA){
          try{
            const thumbResp=await fetch(item.thumbnail_url,{cf:{image:{format:'webp',quality:88}} as any});
            if(thumbResp.ok){
              const thumbBuf=await thumbResp.arrayBuffer();
              const thumbKey=`photos/instagram-reel-thumbs/${item.id}.webp`;
              await c.env.MEDIA.put(thumbKey,thumbBuf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});
              storedThumb='/media/'+thumbKey;
            }
          }catch{}
        }
        if(exists){
          if(storedThumb){await c.env.DB.prepare('UPDATE videos SET thumbnail_url=? WHERE id=?').bind(storedThumb,exists.id).run();reelsImported++}
          else skipped++;
          continue;
        }
        await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order,thumbnail_url,media_url) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(uid(),item.caption?.split('\n')[0]?.slice(0,100)||'Instagram Reel',item.permalink||'','instagram',item.permalink||'',item.id,category,1,reelsImported,storedThumb,item.media_url||'').run();
        reelsImported++;continue;
      }
      const groupId=item.media_type==='CAROUSEL_ALBUM'?item.id:null;
      const photoCandidates=item.media_type==='CAROUSEL_ALBUM'
        ?(item.children?.data||[]).filter((ch:any)=>ch.media_type==='IMAGE'&&ch.media_url).map((ch:any,idx:number)=>({id:ch.id,media_url:ch.media_url,width:item.width,height:item.height,groupOrder:idx}))
        :(item.media_type==='IMAGE'&&item.media_url?[{id:item.id,media_url:item.media_url,width:item.width,height:item.height,groupOrder:0}]:[]);
      if(!photoCandidates.length){skipped++;continue}
      for(const photo of photoCandidates){
        const exists=await c.env.DB.prepare('SELECT id FROM photos WHERE source=? AND source_id=?').bind('instagram',photo.id).first();
        if(exists){skipped++;continue}
        if(!c.env.MEDIA){
          // Keep the Instagram CDN URL for testing/fallback deployments. Production should bind R2 for durable photo storage.
          await c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,total_score,group_id,group_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid(),'instagram',photo.id,null,photo.media_url,item.caption||'',category,category,autoPublish?'approved':'pending',autoPublish?1:0,Number(photo.width||0)||null,Number(photo.height||0)||null,0,instagramImportedScore(photo),groupId,photo.groupOrder).run();
          photosImported++;continue;
        }
        const img=await fetch(photo.media_url,{cf:{image:{format:'webp',quality:92}} as any});
        if(!img.ok){skipped++;continue}
        const buf=await img.arrayBuffer();const bytes=buf.byteLength;const key=`photos/instagram/${photo.id}.webp`;const importedScore=instagramImportedScore({...photo,bytes});const reservationId=uid();
        if(!(await reserveStorage(c,reservationId,bytes)))return {ok:false,error:'5 GB storage limit reached while importing Instagram photos',status:413,photosImported,reelsImported,skipped};
        try{await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.batch([c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,group_id,group_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid(),'instagram',photo.id,key,'/media/'+key,item.caption||'',category,category,autoPublish?'approved':'pending',autoPublish?1:0,Number(photo.width||0)||null,Number(photo.height||0)||null,bytes,groupId,photo.groupOrder),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes)]);photosImported++;}catch{await c.env.MEDIA.delete(key).catch(()=>{});await releaseStorage(c,reservationId);skipped++;}
      }
    }
    endpoint=data.paging?.next||'';pages++;
  }
  return {ok:true,photosImported,reelsImported,skipped,pages,photoStorageEnabled:Boolean(c.env.MEDIA),username:conn.username||null,nextCursor:endpoint||null};
}

function parseJsonSetting(row:any, fallback:any){try{return row?.value?JSON.parse(row.value):fallback}catch{return fallback}}
async function ensureV3Schema(c:any){await c.env.DB.batch([c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`),c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS careers (id TEXT PRIMARY KEY,title TEXT NOT NULL,requirements TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',salary_disclosed INTEGER NOT NULL DEFAULT 0,salary_text TEXT NOT NULL DEFAULT '',duration TEXT NOT NULL DEFAULT '',valid_until TEXT,google_form_url TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`),c.env.DB.prepare(`INSERT OR IGNORE INTO site_settings(key,value) VALUES ('hero_config','{"count":4,"source":"latest_instagram","photo_ids":[],"interval":7,"transition":"normal"}'),('gallery_config','${DEFAULT_GALLERY_CONFIG}'),('strip_config','{"photo_ids":[]}')`)])}
async function readSetting(c:any,key:string,fallback:any){const row:any=await c.env.DB.prepare('SELECT value FROM site_settings WHERE key=?').bind(key).first();return parseJsonSetting(row,fallback)}
async function writeSetting(c:any,key:string,value:any){await c.env.DB.prepare('INSERT INTO site_settings(key,value,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP').bind(key,JSON.stringify(value)).run()}
async function logActivity(c:any,adminId:string|null,adminName:string,action:string){try{await c.env.DB.prepare('INSERT INTO activity_log(id,admin_id,admin_name,action,created_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP)').bind(uid(),adminId,adminName||'Unknown',action).run()}catch{}}
