app.put('/api/admin/homepage/gallery',requireAuth,async c=>{await ensureV3Schema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const rawSlots=Array.isArray(b.slots)?b.slots:[];if(rawSlots.length<MIN_GALLERY_SLOTS)return c.json({error:`Add at least ${MIN_GALLERY_SLOTS} slots.`},400);if(rawSlots.length>MAX_GALLERY_SLOTS)return c.json({error:`A maximum of ${MAX_GALLERY_SLOTS} slots is allowed.`},400);const pinnedIds:string[]=[];const slots:any[]=[];for(const raw of rawSlots){if(raw&&raw.type==='pinned'){const photoId=textField(raw.photo_id,100);if(!photoId)return c.json({error:'A pinned slot is missing a photo.'},400);pinnedIds.push(photoId);slots.push({type:'pinned',photo_id:photoId})}else{const category=textField(raw?.category,100)||'Other';slots.push({type:'category',category})}}if(pinnedIds.length>MAX_PINNED_SLOTS)return c.json({error:`At most ${MAX_PINNED_SLOTS} slots can be pinned.`},400);if(pinnedIds.length){const placeholders=pinnedIds.map(()=>'?').join(',');const found:any=await c.env.DB.prepare(`SELECT id FROM photos WHERE id IN (${placeholders})`).bind(...pinnedIds).all();const foundIds=new Set((found.results||[]).map((r:any)=>String(r.id)));const missing=pinnedIds.filter(id=>!foundIds.has(id));if(missing.length)return c.json({error:'One or more pinned photos could not be found.'},400)}await writeSetting(c,'gallery_config',{slots,columns:3});const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,'Updated the homepage gallery layout');return c.json({ok:true});});
