app.post('/api/admin/photos/materialize',requireAuth,async c=>{if(!c.env.MEDIA)return c.json({error:'Permanent photo storage is not connected. Bind an R2 bucket as MEDIA first.'},503);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const ids=Array.isArray(b.ids)?b.ids.map((x:any)=>textField(x,100)).filter(Boolean).slice(0,30):[];if(!ids.length)return c.json({error:'No photos selected.'},400);let stored=0,failed=0;for(const id of ids){const p:any=await c.env.DB.prepare('SELECT * FROM photos WHERE id=? LIMIT 1').bind(id).first();if(!p?.image_url||p.r2_key)continue;try{const r=await fetch(p.image_url,{cf:{image:{format:'webp',quality:92}} as any});if(!r.ok)throw new Error('image fetch failed');const buf=await r.arrayBuffer();const key=`photos/instagram/${p.source_id||p.id}.webp`;await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.prepare('UPDATE photos SET r2_key=?,image_url=?,bytes=? WHERE id=?').bind(key,'/media/'+key,buf.byteLength,id).run();stored++}catch{failed++}}return c.json({ok:true,stored,failed});});
app.post('/api/admin/photos/materialize-all',requireAuth,async c=>{if(!c.env.MEDIA)return c.json({error:'Permanent photo storage is not connected. Bind an R2 bucket as MEDIA first.'},503);const totalUnmigrated:any=await c.env.DB.prepare("SELECT COUNT(*) n FROM photos WHERE r2_key IS NULL AND image_url IS NOT NULL AND image_url NOT LIKE '/media/%'").first();console.error('MATERIALIZE_ALL_DEBUG total_unmigrated='+Number(totalUnmigrated?.n||0));const rows=await c.env.DB.prepare("SELECT id,image_url,source,source_id FROM photos WHERE r2_key IS NULL AND image_url IS NOT NULL AND image_url NOT LIKE '/media/%' LIMIT 8").all();console.error('MATERIALIZE_ALL_DEBUG batch_found='+(rows.results||[]).length);const list=(rows.results||[]) as any[];let stored=0,failed=0,refreshed=0;for(const p of list){let url=String(p.image_url);try{let r=await fetch(url,{cf:{image:{format:'webp',quality:92}} as any});if(!r.ok&&p.source==='instagram'&&p.source_id){const fresh=await refreshInstagramMediaUrl(c,p.source_id);if(fresh){url=fresh;await c.env.DB.prepare('UPDATE photos SET image_url=? WHERE id=?').bind(url,p.id).run();refreshed++;r=await fetch(url,{cf:{image:{format:'webp',quality:92}} as any})}}if(!r.ok){console.error('MATERIALIZE_ALL_ERROR',p.id,'status='+r.status,url.slice(0,120));throw new Error('image fetch failed: '+r.status)}const buf=await r.arrayBuffer();const key=`photos/instagram/${p.source_id||p.id}.webp`;await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.prepare('UPDATE photos SET r2_key=?,image_url=?,bytes=? WHERE id=?').bind(key,'/media/'+key,buf.byteLength,p.id).run();stored++}catch(e:any){console.error('MATERIALIZE_ALL_ERROR',p.id,e?.name,e?.message,url.slice(0,120));failed++}}const remaining:any=await c.env.DB.prepare("SELECT COUNT(*) n FROM photos WHERE r2_key IS NULL AND image_url IS NOT NULL AND image_url NOT LIKE '/media/%'").first();return c.json({ok:true,stored,failed,refreshed,remaining:Number(remaining?.n||0)});});
app.post('/api/admin/photos/stack',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const ids=Array.isArray(b.ids)?Array.from(new Set(b.ids.map((x:any)=>textField(x,100)).filter(Boolean))).slice(0,30) as string[]:[];if(ids.length<2)return c.json({error:'Select at least 2 photos to stack together.'},400);const groupId=uid();for(let i=0;i<ids.length;i++)await c.env.DB.prepare('UPDATE photos SET group_id=?,group_order=? WHERE id=?').bind(groupId,i,ids[i]).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Stacked ${ids.length} photos into one tile`);return c.json({ok:true,group_id:groupId});});
