async function ensureYouTubeIgnoreSchema(c:any){await c.env.DB.batch([c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS youtube_sync_ignores (id TEXT PRIMARY KEY,video_id TEXT NOT NULL,source_url TEXT NOT NULL UNIQUE,title TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'Other',deleted_at INTEGER NOT NULL)`),c.env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_youtube_sync_ignores_video ON youtube_sync_ignores(video_id)')])}
async function ensureInstagramReelIgnoreSchema(c:any){await c.env.DB.batch([c.env.DB.prepare(`CREATE TABLE IF NOT EXISTS instagram_reel_ignores (id TEXT PRIMARY KEY,video_id TEXT NOT NULL,source_url TEXT NOT NULL UNIQUE,title TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'Other',deleted_at INTEGER NOT NULL)`),c.env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_instagram_reel_ignores_video ON instagram_reel_ignores(video_id)')])}
async function syncYouTubeData(c:any){await ensureYouTubeIgnoreSchema(c);if(!c.env.YOUTUBE_API_KEY)throw new Error('YouTube is not connected. Add YOUTUBE_API_KEY to Worker secrets.');const handle=c.env.YOUTUBE_CHANNEL_HANDLE||'@impressionphotography9904';const base='https://www.googleapis.com/youtube/v3';const ch=await fetch(`${base}/channels?part=contentDetails&forHandle=${encodeURIComponent(handle)}&key=${encodeURIComponent(c.env.YOUTUBE_API_KEY)}`);const chData:any=await ch.json();if(!ch.ok||!chData.items?.[0])throw new Error(chData?.error?.message||'YouTube channel not found');const uploads=chData.items[0].contentDetails.relatedPlaylists.uploads;const serviceRows:any[]=(await c.env.DB.prepare('SELECT title,instagram_hashtags FROM services WHERE active=1 ORDER BY sort_order,id').all()).results;let pageToken='',imported=0,skipped=0,pages=0;do{const url=`${base}/playlistItems?part=snippet,contentDetails,status&playlistId=${encodeURIComponent(uploads)}&maxResults=50${pageToken?`&pageToken=${encodeURIComponent(pageToken)}`:''}&key=${encodeURIComponent(c.env.YOUTUBE_API_KEY)}`;const r=await fetch(url);const data:any=await r.json();if(!r.ok)throw new Error(data?.error?.message||'YouTube API request failed');for(const item of(data.items||[])){const id=item.contentDetails?.videoId||item.snippet?.resourceId?.videoId;if(!id||item.status?.privacyStatus!=='public')continue;const sourceUrl=`https://www.youtube.com/watch?v=${id}`;const ignored=await c.env.DB.prepare('SELECT id FROM youtube_sync_ignores WHERE source_url=? OR video_id=? LIMIT 1').bind(sourceUrl,id).first();if(ignored){skipped++;continue}const exists=await c.env.DB.prepare('SELECT id FROM videos WHERE source_url=?').bind(sourceUrl).first();if(exists){skipped++;continue}const title=String(item.snippet?.title||'YouTube Video');const category=instagramCategory(item.snippet?.description||'',serviceRows);await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid(),title,`https://www.youtube.com/embed/${encodeURIComponent(id)}?enablejsapi=1&playsinline=1&rel=0&modestbranding=1`,'youtube',sourceUrl,id,category,1,imported).run();imported++}pageToken=data.nextPageToken||'';pages++;if(pages>=20)pageToken='';}while(pageToken);return {ok:true,imported,skipped,handle,pages};}
app.post('/api/admin/youtube/sync',requireAuth,async c=>{try{return c.json(await syncYouTubeData(c))}catch(e:any){return c.json({error:String(e?.message||e||'YouTube sync failed')},502)}});
app.post('/api/admin/youtube/reset',requireAuth,async c=>{await ensureYouTubeIgnoreSchema(c);await c.env.DB.prepare('DELETE FROM youtube_sync_ignores').run();try{return c.json(await syncYouTubeData(c))}catch(e:any){return c.json({error:String(e?.message||e||'YouTube reset failed')},502)}});
app.get('/media/*',async c=>{if(!c.env.MEDIA)return c.notFound();const key=c.req.path.replace(/^\/media\//,'');const obj=await c.env.MEDIA.get(key);if(!obj)return c.notFound();const h=new Headers();obj.writeHttpMetadata(h);h.set('etag',obj.httpEtag);return new Response(obj.body,{headers:h});});
app.patch('/api/admin/photos/:id',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const out:any={};if('occasion' in b){if(String(b.occasion).length>100)return c.json({error:'Occasion is too long'},400);out.occasion=textField(b.occasion,100)}if('category' in b){if(String(b.category).length>100)return c.json({error:'Category is too long'},400);out.category=textField(b.category,100)}if('status' in b){if(!['pending','approved','rejected'].includes(String(b.status)))return c.json({error:'Invalid photo status'},400);out.status=String(b.status)}if('published' in b){if(typeof b.published!=='boolean'&&b.published!==0&&b.published!==1)return c.json({error:'Invalid published value'},400);out.published=b.published?1:0}if('caption' in b){if(String(b.caption).length>2000)return c.json({error:'Caption is too long'},400);out.caption=textField(b.caption,2000)}if('total_score' in b){const n=Number(b.total_score);if(!Number.isFinite(n)||n<-100000||n>100000)return c.json({error:'Invalid score'},400);out.total_score=n}if('focal_x' in b){const n=finiteNumber(b.focal_x,0,100,50);out.focal_x=n}if('focal_y' in b){const n=finiteNumber(b.focal_y,0,100,50);out.focal_y=n}if('focal_zoom' in b){const n=finiteNumber(b.focal_zoom,1,2.5,1);out.focal_zoom=n}if('focal_x_mobile' in b){out.focal_x_mobile=b.focal_x_mobile==null?null:finiteNumber(b.focal_x_mobile,0,100,50)}if('focal_y_mobile' in b){out.focal_y_mobile=b.focal_y_mobile==null?null:finiteNumber(b.focal_y_mobile,0,100,50)}if('focal_zoom_mobile' in b){out.focal_zoom_mobile=b.focal_zoom_mobile==null?null:finiteNumber(b.focal_zoom_mobile,1,2.5,1)}if('focal_x_hero' in b){out.focal_x_hero=b.focal_x_hero==null?null:finiteNumber(b.focal_x_hero,0,100,50)}if('focal_y_hero' in b){out.focal_y_hero=b.focal_y_hero==null?null:finiteNumber(b.focal_y_hero,0,100,50)}if('focal_zoom_hero' in b){out.focal_zoom_hero=b.focal_zoom_hero==null?null:finiteNumber(b.focal_zoom_hero,1,2.5,1)}if('focal_x_hero_mobile' in b){out.focal_x_hero_mobile=b.focal_x_hero_mobile==null?null:finiteNumber(b.focal_x_hero_mobile,0,100,50)}if('focal_y_hero_mobile' in b){out.focal_y_hero_mobile=b.focal_y_hero_mobile==null?null:finiteNumber(b.focal_y_hero_mobile,0,100,50)}if('focal_zoom_hero_mobile' in b){out.focal_zoom_hero_mobile=b.focal_zoom_hero_mobile==null?null:finiteNumber(b.focal_zoom_hero_mobile,1,2.5,1)}if('excluded_from_auto' in b){if(typeof b.excluded_from_auto!=='boolean'&&b.excluded_from_auto!==0&&b.excluded_from_auto!==1)return c.json({error:'Invalid excluded_from_auto value'},400);out.excluded_from_auto=b.excluded_from_auto?1:0}const keys=Object.keys(out);if(!keys.length)return c.json({ok:true});await c.env.DB.prepare(`UPDATE photos SET ${keys.map(x=>`${x}=?`).join(',')},updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(...keys.map(k=>out[k]),c.req.param('id')).run();if('status' in out){const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Set a photo's status to ${out.status}`)}return c.json({ok:true});});
app.delete('/api/admin/photos/:id',requireAuth,async c=>{const id=c.req.param('id');const p:any=await c.env.DB.prepare('SELECT r2_key FROM photos WHERE id=?').bind(id).first();if(p?.r2_key&&c.env.MEDIA)await c.env.MEDIA.delete(p.r2_key);await c.env.DB.prepare('DELETE FROM photos WHERE id=?').bind(id).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,'Deleted a photo');return c.json({ok:true});});
app.get('/api/admin/services',requireAuth,async c=>c.json((await c.env.DB.prepare('SELECT id,title,description,image_url,active,sort_order,instagram_hashtags FROM services ORDER BY sort_order,id').all()).results));
app.post('/api/admin/services',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const title=textField(b.title,200),description=textField(b.description,5000),imageUrl=textField(b.image_url,2048),instagramHashtags=textField(b.instagram_hashtags,1000),sortOrder=boundedInt(b.sort_order,-10000,10000,0),price=finiteNumber(b.price,0,100000000,0);if(!title)return c.json({error:'Service title is required'},400);if(!validMediaUrl(imageUrl))return c.json({error:'Image URL must use http(s) or /media/'},400);if(String(b.title||'').length>200||String(b.description||'').length>5000||String(b.image_url||'').length>2048||String(b.instagram_hashtags||'').length>1000)return c.json({error:'Service fields are too long'},400);const id=textField(b.id,100)||uid();await c.env.DB.prepare(`INSERT INTO services(id,title,description,price,image_url,active,sort_order,instagram_hashtags) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,price=excluded.price,image_url=excluded.image_url,active=excluded.active,sort_order=excluded.sort_order,instagram_hashtags=excluded.instagram_hashtags`).bind(id,title,description,price,imageUrl,b.active===false?0:1,sortOrder,instagramHashtags).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Saved category "${title}"`);return c.json({ok:true,id});});
app.delete('/api/admin/services/:id',requireAuth,async c=>{await c.env.DB.prepare('DELETE FROM services WHERE id=?').bind(c.req.param('id')).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,'Deleted a category');return c.json({ok:true});});
app.get('/api/admin/hashtags',requireAuth,async c=>{await ensureHashtagSightingsSchema(c);const rows=(await c.env.DB.prepare('SELECT hashtag,count,last_seen,sample_caption FROM hashtag_sightings WHERE dismissed=0 ORDER BY count DESC,last_seen DESC LIMIT 100').all()).results;return c.json(rows||[])});
app.post('/api/admin/hashtags/resolve',requireAuth,async c=>{await ensureHashtagSightingsSchema(c);await ensureCategoryAliasSchema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const alias=normalizeInstagramHashtag(String(b.alias||''));const category=textField(b.category,100);const originalHashtag=b.hashtag?normalizeInstagramHashtag(String(b.hashtag)):'';if(!alias)return c.json({error:'Enter a hashtag to match on'},400);if(!category)return c.json({error:'Enter or choose a category'},400);await c.env.DB.prepare('INSERT INTO category_hashtag_aliases(hashtag,category) VALUES(?,?) ON CONFLICT(hashtag) DO UPDATE SET category=excluded.category').bind(alias,category).run();if(originalHashtag)await c.env.DB.prepare('DELETE FROM hashtag_sightings WHERE hashtag=?').bind(originalHashtag).run();const candidates:any[]=(await c.env.DB.prepare("SELECT id,caption FROM photos WHERE published=0 AND caption LIKE ?").bind('%#'+alias+'%').all()).results||[];let updated=0;for(const p of candidates){const tags=(String(p.caption||'').match(/#[\p{L}0-9_-]+/gu)||[]).map((t:string)=>normalizeInstagramHashtag(t));if(!tags.some(t=>t.includes(alias)))continue;await c.env.DB.prepare('UPDATE photos SET category=?,occasion=?,status=?,published=1,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(category,category,'approved',p.id).run();updated++}return c.json({ok:true,updated})});
app.post('/api/admin/hashtags/:hashtag/dismiss',requireAuth,async c=>{await ensureHashtagSightingsSchema(c);await c.env.DB.prepare('UPDATE hashtag_sightings SET dismissed=1 WHERE hashtag=?').bind(normalizeInstagramHashtag(decodeURIComponent(c.req.param('hashtag')))).run();return c.json({ok:true})});
