app.get('/api/admin/youtube/ignored',requireAuth,async c=>{await ensureYouTubeIgnoreSchema(c);return c.json({videos:(await c.env.DB.prepare('SELECT * FROM youtube_sync_ignores ORDER BY deleted_at DESC').all()).results||[]})});
app.post('/api/admin/videos',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=textField(b.id,100)||uid();const platform=String(b.platform||'youtube')==='instagram'?'instagram':'youtube';const sourceUrl=textField(b.source_url||b.embed_url,2048);let title=textField(b.title,200);const category=textField(b.category||'Other',100);if(!sourceUrl)return c.json({error:'Video link is required'},400);if(String(b.title||'').length>200||String(b.source_url||b.embed_url||'').length>2048||String(b.category||'Other').length>100)return c.json({error:'Video fields are too long'},400);let videoId='';let embedUrl=sourceUrl;try{const u=new URL(sourceUrl);if(platform==='youtube'){const host=u.hostname.toLowerCase().replace(/^www\./,'');if(!['youtube.com','m.youtube.com','youtu.be','youtube-nocookie.com'].includes(host))return c.json({error:'Invalid YouTube link'},400);if(host==='youtu.be')videoId=u.pathname.slice(1).split('/')[0];else if(u.searchParams.get('v'))videoId=u.searchParams.get('v')||'';else videoId=u.pathname.match(/\/(?:embed|shorts|live)\/([^/?]+)/)?.[1]||'';if(!videoId)return c.json({error:'Invalid YouTube link'},400);embedUrl=`https://www.youtube.com/embed/${encodeURIComponent(videoId)}?enablejsapi=1&playsinline=1&rel=0&modestbranding=1`;if(!title&&c.env.YOUTUBE_API_KEY){const metaResp=await fetch(`https://www.googleapis.com/youtube/v3/videos?part=snippet&id=${encodeURIComponent(videoId)}&key=${encodeURIComponent(c.env.YOUTUBE_API_KEY)}`);const meta:any=await metaResp.json();if(metaResp.ok&&meta.items?.[0]?.snippet?.title)title=String(meta.items[0].snippet.title).slice(0,200)}}else if(platform==='instagram'){if(!/instagram\.com$/i.test(u.hostname)&&!/.instagram\.com$/i.test(u.hostname))return c.json({error:'Invalid Instagram link'},400);const m=u.pathname.match(/\/reel\/([^/?#]+)/);if(!m)return c.json({error:'Use an Instagram Reel URL'},400);embedUrl=`https://www.instagram.com/reel/${m[1]}/embed/?hidecaption=1`;}}catch{return c.json({error:'Invalid video URL'},400)}if(platform==='youtube'){await ensureYouTubeIgnoreSchema(c);await c.env.DB.prepare('DELETE FROM youtube_sync_ignores WHERE source_url=? OR video_id=?').bind(sourceUrl,videoId).run();if(!title)title='YouTube Video'}if(!title)return c.json({error:'Video title could not be determined'},400);await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,embed_url=excluded.embed_url,platform=excluded.platform,source_url=excluded.source_url,video_id=excluded.video_id,category=excluded.category,active=excluded.active,sort_order=excluded.sort_order`).bind(id,title,embedUrl,platform,sourceUrl,videoId,category,b.active===false?0:1,boundedInt(b.sort_order,-10000,10000,0)).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Added a ${platform} video: "${title}"`);return c.json({ok:true,id});});
app.delete('/api/admin/videos/:id',requireAuth,async c=>{await ensureYouTubeIgnoreSchema(c);await ensureInstagramReelIgnoreSchema(c);const id=c.req.param('id');const v:any=await c.env.DB.prepare('SELECT id,title,platform,source_url,video_id,category,thumbnail_url FROM videos WHERE id=?').bind(id).first();if(!v)return c.json({error:'Video not found'},404);if(v.thumbnail_url&&String(v.thumbnail_url).startsWith('/media/')&&c.env.MEDIA)await c.env.MEDIA.delete(String(v.thumbnail_url).replace(/^\/media\//,'')).catch(()=>{});if(String(v.platform||'youtube')==='youtube'&&v.video_id){const sourceUrl=String(v.source_url||`https://www.youtube.com/watch?v=${v.video_id}`);await c.env.DB.prepare('INSERT INTO youtube_sync_ignores(id,video_id,source_url,title,category,deleted_at) VALUES(?,?,?,?,?,?) ON CONFLICT(source_url) DO UPDATE SET video_id=excluded.video_id,title=excluded.title,category=excluded.category,deleted_at=excluded.deleted_at').bind(uid(),String(v.video_id),sourceUrl,String(v.title||'YouTube video'),String(v.category||'Other'),Date.now()).run()}else if(String(v.platform)==='instagram'&&v.video_id){const sourceUrl=String(v.source_url||'');await c.env.DB.prepare('INSERT INTO instagram_reel_ignores(id,video_id,source_url,title,category,deleted_at) VALUES(?,?,?,?,?,?) ON CONFLICT(source_url) DO UPDATE SET video_id=excluded.video_id,title=excluded.title,category=excluded.category,deleted_at=excluded.deleted_at').bind(uid(),String(v.video_id),sourceUrl,String(v.title||'Instagram Reel'),String(v.category||'Other'),Date.now()).run()}await c.env.DB.prepare('DELETE FROM videos WHERE id=?').bind(id).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Deleted a ${v.platform||'youtube'} video: "${v.title||''}"`);return c.json({ok:true});});
app.post('/api/admin/youtube/ignored/:id/reimport',requireAuth,async c=>{await ensureYouTubeIgnoreSchema(c);const id=c.req.param('id');const row:any=await c.env.DB.prepare('SELECT video_id FROM youtube_sync_ignores WHERE id=?').bind(id).first();if(!row)return c.json({error:'Ignored video not found'},404);await c.env.DB.prepare('DELETE FROM youtube_sync_ignores WHERE id=?').bind(id).run();try{const result=await syncYouTubeData(c);return c.json({ok:true,...result})}catch(e:any){return c.json({error:String(e?.message||'YouTube sync failed')},502)}});
app.get('/api/admin/careers',requireAuth,async c=>{await ensureV3Schema(c);return c.json((await c.env.DB.prepare('SELECT * FROM careers ORDER BY active DESC, valid_until IS NULL, valid_until, sort_order, created_at DESC').all()).results)});
app.post('/api/admin/careers',requireAuth,async c=>{await ensureV3Schema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=textField(b.id,100)||uid(),title=textField(b.title,200),requirements=textField(b.requirements,5000),description=textField(b.description,8000),salaryText=textField(b.salary_text,300),duration=textField(b.duration,200),validUntil=textField(b.valid_until,10),formUrl=textField(b.google_form_url,2048),sortOrder=boundedInt(b.sort_order,-10000,10000,0);if(!title)return c.json({error:'Job title is required'},400);if(validUntil&&!/^\d{4}-\d{2}-\d{2}$/.test(validUntil))return c.json({error:'Validity date must be YYYY-MM-DD'},400);if(formUrl){try{const u=new URL(formUrl);if(u.protocol!=='https:')return c.json({error:'Google Form link must use HTTPS'},400)}catch{return c.json({error:'Invalid Google Form link'},400)}}if(String(b.title||'').length>200||String(b.requirements||'').length>5000||String(b.description||'').length>8000||String(b.salary_text||'').length>300||String(b.duration||'').length>200||String(b.google_form_url||'').length>2048)return c.json({error:'Career fields are too long'},400);await c.env.DB.prepare(`INSERT INTO careers(id,title,requirements,description,salary_disclosed,salary_text,duration,valid_until,google_form_url,active,sort_order,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET title=excluded.title,requirements=excluded.requirements,description=excluded.description,salary_disclosed=excluded.salary_disclosed,salary_text=excluded.salary_text,duration=excluded.duration,valid_until=excluded.valid_until,google_form_url=excluded.google_form_url,active=excluded.active,sort_order=excluded.sort_order,updated_at=CURRENT_TIMESTAMP`).bind(id,title,requirements,description,b.salary_disclosed?1:0,salaryText,duration,validUntil||null,formUrl,b.active===false?0:1,sortOrder).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Saved job listing "${title}"`);return c.json({ok:true,id});});
app.patch('/api/admin/careers/:id',requireAuth,async c=>{await ensureV3Schema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}if(typeof b.active==='boolean'||b.active===0||b.active===1){await c.env.DB.prepare('UPDATE careers SET active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(b.active?1:0,c.req.param('id')).run();return c.json({ok:true})}return c.json({error:'No supported field to update'},400)});
app.delete('/api/admin/careers/:id',requireAuth,async c=>{await ensureV3Schema(c);await c.env.DB.prepare('DELETE FROM careers WHERE id=?').bind(c.req.param('id')).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,'Deleted a job listing');return c.json({ok:true});});
app.get('/api/admin/admins',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);await ensureAdminInvitationsSchema(c);return c.json((await c.env.DB.prepare('SELECT id,name,email,role,active,created_at FROM admins ORDER BY created_at').all()).results)});
app.get('/api/admin/activity-log',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);const r=await c.env.DB.prepare('SELECT id,admin_name,action,created_at FROM activity_log ORDER BY created_at DESC LIMIT 2000').all();return c.json(r.results||[])});
app.post('/api/admin/admin-invites',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);await ensureAdminInvitationsSchema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const email=String(b.email||'').trim().toLowerCase();if(!validEmail(email))return c.json({error:'Enter a valid email address'},400);if(!(await rateLimit(c,`admin-invite-ip:${clientIp(c)}`,20,60*60*1000,60*60*1000)))return c.json({error:'Too many invitations. Please try again later.'},429);if(setupOwnerEmails(c.env).includes(email))return c.json({error:'The Owner email cannot be invited as an admin.'},400);const existing:any=await c.env.DB.prepare('SELECT id FROM admins WHERE email=? LIMIT 1').bind(email).first();if(existing)return c.json({error:'That email is already an admin'},409);const now=Date.now();await c.env.DB.prepare('DELETE FROM admin_invitations WHERE expires_at<=? OR used_at IS NOT NULL').bind(now).run();const previous:any=await c.env.DB.prepare('SELECT id FROM admin_invitations WHERE email=? AND used_at IS NULL ORDER BY created_at DESC LIMIT 1').bind(email).first();if(previous)await c.env.DB.prepare('DELETE FROM admin_invitations WHERE id=?').bind(previous.id).run();const counts:any=await c.env.DB.prepare(`SELECT (SELECT COUNT(*) FROM admins WHERE role='admin' AND active=1) active_count,(SELECT COUNT(*) FROM admin_invitations WHERE used_at IS NULL AND expires_at>?) pending_count`).bind(now).first();if(Number(counts?.active_count||0)+Number(counts?.pending_count||0)>=5)return c.json({error:'The maximum of 5 Admin accounts has been reached. Delete an Admin or wait for an invitation to expire.'},409);const raw=b64u(crypto.getRandomValues(new Uint8Array(32)));const tokenHash=await sha256(raw);const id=uid();const expiresAt=now+12*60*60*1000;const url=new URL('/admin/invite',c.req.url);url.searchParams.set('token',raw);await c.env.DB.prepare('INSERT INTO admin_invitations(id,email,token_hash,expires_at) VALUES(?,?,?,?)').bind(id,email,tokenHash,expiresAt).run();await logActivity(c,me.id,me.name||me.email,`Invited ${email} as an admin`);try{await sendAdminInvitation(c,email,url.toString())}catch(e:any){console.error('ADMIN_INVITE_EMAIL_ERROR',e?.name||'Error',e?.message||String(e));return c.json({ok:false,inviteUrl:url.toString(),expiresAt,error:'The invitation email could not be delivered. The invitation is still valid; use the invitation link to complete setup, or verify the Resend sender/domain configuration.'},503)}return c.json({ok:true,expiresAt});});
app.get('/api/admin/admin-invites/:token',async c=>{await ensureAdminInvitationsSchema(c);const raw=c.req.param('token');if(!raw||raw.length<20)return c.json({error:'Invalid invitation'},400);const row:any=await c.env.DB.prepare('SELECT email,expires_at,used_at FROM admin_invitations WHERE token_hash=? LIMIT 1').bind(await sha256(raw)).first();if(!row||row.used_at)return c.json({error:'This invitation has already been used.'},410);if(Number(row.expires_at)<Date.now())return c.json({error:'This invitation has expired. Ask the Owner to send a new invitation.'},410);return c.json({ok:true,email:row.email,expiresAt:Number(row.expires_at)});});
app.post('/api/admin/invites/complete',async c=>{await ensureAdminInvitationsSchema(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const raw=String(b.token||'');const name=String(b.name||'').trim();const email=String(b.email||'').trim().toLowerCase();const password=String(b.password||'');const confirm=String(b.confirmPassword||'');if(!raw||raw.length<20)return c.json({error:'Invalid invitation'},400);const row:any=await c.env.DB.prepare('SELECT * FROM admin_invitations WHERE token_hash=? LIMIT 1').bind(await sha256(raw)).first();if(!row||row.used_at)return c.json({error:'This invitation has already been used.'},410);if(Number(row.expires_at)<Date.now())return c.json({error:'This invitation has expired. Ask the Owner to send a new invitation.'},410);if(email!==String(row.email).toLowerCase())return c.json({error:'The verified email does not match this invitation.'},400);if(!name||name.length>100)return c.json({error:'Enter your name.'},400);if(password.length<12||password.length>128)return c.json({error:'Password must be 12–128 characters.'},400);if(password!==confirm)return c.json({error:'Passwords do not match'},400);const active:any=await c.env.DB.prepare(`SELECT COUNT(*) n FROM admins WHERE role='admin' AND active=1`).first();if(Number(active?.n||0)>=5)return c.json({error:'The maximum of 5 Admin accounts has been reached.'},409);const adminId=uid();try{const passwordHash=await hashPassword(password);const result=await c.env.DB.batch([c.env.DB.prepare('INSERT INTO admins(id,name,email,password_hash,role,active) VALUES(?,?,?,?,?,1)').bind(adminId,name,email,passwordHash,'admin'),c.env.DB.prepare('UPDATE admin_invitations SET used_at=? WHERE id=? AND used_at IS NULL').bind(Date.now(),row.id)]);if(result.some((r:any)=>r?.success===false))throw new Error('Database batch returned an unsuccessful statement');await logActivity(c,adminId,name,'Joined as an admin (accepted invitation)')}catch(e:any){if(String(e?.message||'').toLowerCase().includes('unique'))return c.json({error:'That email is already an admin'},409);console.error('ADMIN_INVITE_COMPLETE_ERROR',e?.name||'Error',e?.message||String(e));return c.json({error:'Admin account could not be created. Please try again.'},500)}return c.json({ok:true});});
app.delete('/api/admin/admins/:id',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);if(c.req.param('id')===me.id)return c.json({error:'Cannot delete yourself'},400);const target:any=await c.env.DB.prepare('SELECT name,email FROM admins WHERE id=?').bind(c.req.param('id')).first();await c.env.DB.prepare("DELETE FROM admins WHERE id=? AND role='admin'").bind(c.req.param('id')).run();await logActivity(c,me.id,me.name||me.email,`Removed admin ${target?.name||target?.email||''}`);return c.json({ok:true})});
app.post('/api/admin/admins/:id/make-owner',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);const targetId=c.req.param('id');if(targetId===me.id)return c.json({error:'You are already the Owner.'},400);const target:any=await c.env.DB.prepare("SELECT id,name,email,active FROM admins WHERE id=? AND role='admin'").bind(targetId).first();if(!target)return c.json({error:'Admin not found.'},404);if(!target.active)return c.json({error:'This admin account is not active.'},400);const result=await c.env.DB.batch([c.env.DB.prepare("UPDATE admins SET role='owner' WHERE id=?").bind(targetId),c.env.DB.prepare("UPDATE admins SET role='admin' WHERE id=?").bind(me.id)]);if(result.some((r:any)=>r?.success===false))return c.json({error:'Ownership transfer failed. Please try again.'},500);await logActivity(c,me.id,me.name||me.email,`Transferred Owner access to ${target.name||target.email}`);return c.json({ok:true})});
app.post('/api/contact',async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const name=textField(b.name,150),email=String(b.email||'').trim().toLowerCase(),phone=textField(b.phone,40),message=textField(b.message,3000);if(!name||!validEmail(email)||!message)return c.json({error:'Please fill in your name, a valid email, and a message.'},400);const ip=clientIp(c);if(!(await rateLimit(c,`contact-ip:${ip}`,5,60*60*1000,60*60*1000)))return c.json({error:'Too many messages sent. Please try again later.'},429);await c.env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_messages (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT DEFAULT \'\',message TEXT NOT NULL,email_sent INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)').run();const msgId=uid();await c.env.DB.prepare('INSERT INTO contact_messages(id,name,email,phone,message) VALUES(?,?,?,?,?)').bind(msgId,name,email,phone,message).run();const owners=setupOwnerEmails(c.env);const to=owners.length?owners:(c.env.ADMIN_OWNER_EMAIL?[c.env.ADMIN_OWNER_EMAIL]:[]);if(!c.env.RESEND_API_KEY||!c.env.RESEND_FROM_EMAIL||!to.length){return c.json({ok:true,emailed:false})}const esc=(s:string)=>s.replace(/[<>]/g,'');try{const resp=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${c.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:c.env.RESEND_FROM_EMAIL,to,reply_to:email,subject:`New enquiry from ${esc(name)} — Impression Photography website`,html:emailWrapper(`<h2 style="margin:0 0 6px;font-family:Georgia,serif;font-size:20px;color:#14181b">New website enquiry</h2><p style="margin:0 0 18px;color:#5b6167">Someone reached out through your Contact page.</p><p style="margin:0 0 6px"><b>Name:</b> ${esc(name)}</p><p style="margin:0 0 6px"><b>Email:</b> ${esc(email)}</p>${phone?`<p style="margin:0 0 6px"><b>Phone:</b> ${esc(phone)}</p>`:''}<p style="margin:18px 0 6px;color:#8a8478;font-size:13px">Message</p><p style="margin:0;white-space:pre-wrap">${esc(message).replace(/\n/g,'<br/>')}</p>`)})});if(resp.ok){await c.env.DB.prepare('UPDATE contact_messages SET email_sent=1 WHERE id=?').bind(msgId).run()}else{const detail=await resp.text().catch(()=>'');console.error('CONTACT_EMAIL_ERROR',detail)}}catch(e:any){console.error('CONTACT_EMAIL_ERROR',e?.message||String(e))}return c.json({ok:true,emailed:true})});
app.get('/api/admin/contact-messages',requireAuth,async c=>{await c.env.DB.prepare('CREATE TABLE IF NOT EXISTS contact_messages (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT DEFAULT \'\',message TEXT NOT NULL,email_sent INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)').run();const rows=(await c.env.DB.prepare('SELECT * FROM contact_messages ORDER BY created_at DESC LIMIT 300').all()).results;return c.json(rows||[])});
