app.get('/api/admin/testimonials',requireAuth,async c=>{await ensureInterimTestimonialsTable(c);const rows:any=await c.env.DB.prepare('SELECT id,author_name,rating,review_text,relative_time,verified,active,sort_order,image_url,created_at FROM testimonials ORDER BY sort_order,created_at DESC').all();return c.json(rows.results||[])});
app.post('/api/admin/testimonials',requireAuth,async c=>{await ensureInterimTestimonialsTable(c);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=textField(b.id,100)||uid(),author=textField(b.author_name,100),text=textField(b.review_text,1000),relative=textField(b.relative_time,60),image=textField(b.image_url,500),rating=Math.max(1,Math.min(5,Math.round(Number(b.rating)||5))),sortOrder=boundedInt(b.sort_order,-10000,10000,0);if(!author)return c.json({error:"Enter the reviewer's name."},400);if(String(b.review_text||'').length>1000)return c.json({error:'Review text is too long.'},400);await c.env.DB.prepare(`INSERT INTO testimonials(id,source,author_name,rating,review_text,relative_time,verified,active,sort_order,image_url) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET author_name=excluded.author_name,rating=excluded.rating,review_text=excluded.review_text,relative_time=excluded.relative_time,verified=excluded.verified,active=excluded.active,sort_order=excluded.sort_order,image_url=excluded.image_url`).bind(id,'manual',author,rating,text,relative,b.verified===false?0:1,b.active===false?0:1,sortOrder,image).run();const me:any=c.get('admin');await logActivity(c,me.id,me.name||me.email,`Saved a testimonial from "${author}"`);return c.json({ok:true,id})});
