const BOT_UA_PATTERN=/bot|spider|crawl|slurp|headless|phantomjs|puppeteer|playwright|selenium|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|site24x7|nessus|nmap|sqlmap|nikto|masscan|zgrab|censys|shodan|ahrefsbot|semrushbot|mj12bot|dotbot|facebookexternalhit|twitterbot|linkedinbot|slackbot|whatsapp|telegrambot|discordbot|archive\.org|ia_archiver|go-http-client|python-requests|curl\/|wget\/|okhttp|axios\/|node-fetch|postmanruntime|insomnia|scrapy|httpclient/i;
const CLICK_ACTIONS=new Set(['whatsapp_nav','whatsapp_hero','whatsapp_bubble','whatsapp_widget_chat','whatsapp_contact_card','call_click']);
app.post('/api/track-click',async c=>{const uaRaw=c.req.header('user-agent')||'';if(!uaRaw||BOT_UA_PATTERN.test(uaRaw))return c.json({ok:true,skipped:true});let body:any={};try{body=await c.req.json()}catch{}const action=String(body?.action||'');if(!CLICK_ACTIONS.has(action))return c.json({ok:true,skipped:true});const day=new Date().toISOString().slice(0,10);await c.env.DB.prepare(`INSERT INTO analytics_clicks(day,action,count) VALUES(?,?,1) ON CONFLICT(day,action) DO UPDATE SET count=count+1`).bind(day,action).run();return c.json({ok:true})});
app.post('/api/analytics',async c=>{const uaRaw=c.req.header('user-agent')||'';if(!uaRaw||BOT_UA_PATTERN.test(uaRaw))return c.json({ok:true,skipped:true});if(await session(c,c.env))return c.json({ok:true,skipped:true});const day=new Date().toISOString().slice(0,10);const m=c.req.header('sec-ch-ua-mobile')==='?1';const ua=uaRaw.toLowerCase();const device=m?'mobile':(/ipad|tablet|android(?!.*mobile)/.test(ua)?'tablet':'desktop');const seen=getCookie(c,'ip_visitor')==='1';await c.env.DB.prepare(`INSERT INTO analytics_daily(day,visitors,pageviews,mobile,desktop,tablet,other) VALUES(?,${seen?0:1},1,${device==='mobile'?1:0},${device==='desktop'?1:0},${device==='tablet'?1:0},${device==='other'?1:0}) ON CONFLICT(day) DO UPDATE SET visitors=visitors+excluded.visitors,pageviews=pageviews+1,mobile=mobile+excluded.mobile,desktop=desktop+excluded.desktop,tablet=tablet+excluded.tablet,other=other+excluded.other`).bind(day).run();if(!seen)setCookie(c,'ip_visitor','1',{httpOnly:true,secure:true,sameSite:'Lax',path:'/',maxAge:86400});return c.json({ok:true});});
app.all('*',c=>c.env.ASSETS?.fetch(c.req.raw) || c.notFound());
export default {fetch:app.fetch,scheduled:async(_controller:any,env:Env)=>{try{const now=Date.now();const orphaned:any=await env.DB.prepare('SELECT id,reservation_id,key FROM upload_nonces WHERE uploaded_at IS NOT NULL AND uploaded_at<? LIMIT 100').bind(now-60*60*1000).all();for(const n of(orphaned.results||[])){const photo:any=await env.DB.prepare('SELECT id FROM photos WHERE r2_key=? LIMIT 1').bind(n.key).first();if(photo){await env.DB.prepare('DELETE FROM upload_nonces WHERE id=?').bind(n.id).run();continue}if(env.MEDIA)await env.MEDIA.delete(n.key).catch(()=>{});await releaseStorage({env} as any,n.reservation_id);await env.DB.prepare('DELETE FROM upload_nonces WHERE id=?').bind(n.id).run();}const staleUploads:any=await env.DB.prepare('SELECT id,reservation_id,key FROM upload_nonces WHERE used_at IS NOT NULL AND uploaded_at IS NULL AND used_at<? LIMIT 100').bind(now-60*60*1000).all();for(const n of(staleUploads.results||[])){if(env.MEDIA)await env.MEDIA.delete(n.key).catch(()=>{});await releaseStorage({env} as any,n.reservation_id);await env.DB.prepare('DELETE FROM upload_nonces WHERE id=?').bind(n.id).run();}await env.DB.batch([env.DB.prepare('DELETE FROM sessions WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM setup_verifications WHERE used_at IS NOT NULL OR expires_at<?').bind(now),env.DB.prepare('DELETE FROM auth_rate_limits WHERE window_start<? AND blocked_until<?').bind(now-24*60*60*1000,now),env.DB.prepare('DELETE FROM upload_nonces WHERE expires_at<? AND uploaded_at IS NULL').bind(now),env.DB.prepare("DELETE FROM contact_messages WHERE created_at<datetime('now','-90 days')"),env.DB.prepare("DELETE FROM activity_log WHERE created_at<datetime('now','-60 days')")]);const stale:any=await env.DB.prepare('SELECT id FROM storage_reservations WHERE expires_at<?').bind(now).all();for(const r of(stale.results||[]))await releaseStorage({env} as any,r.id);await syncInstagramData({env});await syncYouTubeData({env} as any).catch(()=>{})}catch{}}};
